const CHAPTERS: VizChapter[] = [{"id":"mw-ch01","subj":"middleware","title":"Redis 数据结构与底层编码","summary":"String/List/Hash/Set/ZSet 与 Bitmap/HyperLogLog/GEO/Stream 的场景；SDS 与 C 字符串的差异（长度前缀、二进制安全、预分配）；ziplist/listpack/quicklist/…","concepts":[{"id":"mw-ch01/01-sds-and-string","file":"01-sds-and-string.md","title":"一、SDS 与 String 对象编码","kind":"flow","secs":[{"h":"① SDS：Redis 的二进制安全字符串","s":"（中立陈述）Redis 没有直接用 C 原生 \\0 结尾字符串存 key 和 value，而是定义了 sdshdr 结构：除字节数组 buf 外，额外维护 len（已用长度）、alloc（已分配容量），并用 flags 区分不同头部长度…","c":null},{"h":"② String 对象的三种编码","s":"（中立陈述）Redis 的 String 对象 value 按内容选择编码：long 可表示的整数字面量 → OBJ_ENCODING_INT；长度 ≤44 字节的非整数短串 → OBJ_ENCODING_EMBSTR（对象头与 buf…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"class SDS:\n    def __init__(self, s):\n        self.buf = bytearray(s.encode(\"utf-8\", \"surrogatepass\"))\n        self.len = len(self.buf)\n        self.alloc = self.len\n    def _ensure(self, need):\n        if self.alloc >= need:\n            return\n        if self.len < 1024 * 1024:\n…"}}]},{"id":"mw-ch01/02-list-hash-encoding","file":"02-list-hash-encoding.md","title":"二、List 与 Hash 的底层编码","kind":"flow","secs":[{"h":"① List：从 ziplist+linkedlist 到 quicklist","s":"（中立陈述）Redis 3.2 前 List 在元素少时用 ziplist、多时用 linkedlist；3.2 起统一为 quicklist——一个由多个 listpack（Redis 7 起 ziplist 被 listpack 取…","c":null},{"h":"② Hash：listpack 与 hashtable 的编码切换","s":"（中立陈述）Hash 对象在字段数 ≤ hash-max-listpack-entries（默认 128）且每个 value 字节数 ≤ hash-max-listpack-value（默认 64）时编码为 listpack；超出任一条…","c":null}]},{"id":"mw-ch01/03-set-zset-encoding","file":"03-set-zset-encoding.md","title":"三、Set 与 ZSet 的底层编码","kind":"flow","secs":[{"h":"① Set：intset（整数集合）与 hashtable","s":"（中立陈述）Set 当所有元素都是整数且元素个数 ≤ set-max-intset-entries（默认 512）时编码为 intset（一块连续、按值升序排列的整数数组，按 encoding 字段统一用 16/32/64 位存储）；任…","c":null},{"h":"② ZSet：listpack 与 skiplist + dict 双结构","s":"（中立陈述）ZSet 在元素数 ≤ zset-max-listpack-entries（默认 128）且每个 member 字节 ≤ zset-max-listpack-value（默认 64）时用 listpack（member 与…","c":null}]},{"id":"mw-ch01/04-dict-rehash-and-object","file":"04-dict-rehash-and-object.md","title":"四、字典渐进式 rehash 与对象系统","kind":"flow","secs":[{"h":"① dict：渐进式 rehash（不阻塞的单线程友好设计）","s":"（中立陈述）Redis 的 dict 用两张哈希表 ht[0]/ht[1]，负载因子超阈值（或 rehash 中）触发扩容/缩容。它不一次性搬迁全部 entry，而是用 rehashidx 记录进度，在执行增删改查及定时任务 serve…","c":null},{"h":"② redisObject 类型/编码系统与二进制安全","s":"（中立陈述）Redis 一切键值都包成 redisObject：type（五大型）、encoding（底层编码）、refcount（引用计数共享）、lru（LRU/LFU 时钟）。TYPE 看 type，OBJECT ENCODING…","c":null}]},{"id":"mw-ch01/05-redis-data-practical-recipes","file":"05-redis-data-practical-recipes.md","title":"凯喵实战手记 · Redis 底层结构：为什么你的 key 会突然变胖","kind":"flow","secs":[{"h":"现场 1：为什么 Redis 不用 C 字符串","s":"C 字符串以零字节结尾，求长度要遍历，还不安全。Redis 自己实现了 SDS（简单动态字符串），头部记录长度与已分配容量，取长度是常数时间，且二进制安全，能存图片、序列化数据。凯喵提醒：你存进去的每个字符串，底层其实都套着一个 SDS…","c":{"lang":"c","code":"struct sdshdr8 {\n    uint8_t len;      // 已用长度\n    uint8_t alloc;    // 已分配容量（不含头和终止符）\n    unsigned char flags;\n    char buf[];       // 柔性数组，实际内容\n};"}},{"h":"现场 2：SDS 头部按长度自适应","s":"短字符串用 sdshdr5（只存 flags 和内容），中等用 sdshdr8，再长用 16/32/64 位头。头部越小越省内存，但能表达的长度上限越低。凯喵带人排查「为什么一万个短 key 占了这么多内存」时，第一件事就是算：每个 k…","c":null},{"h":"现场 3：字符串的三种编码：int、embstr、raw","s":"Redis 会看内容挑最省的编码。能解析成 64 位整数的用 int，直接把数值存在指针位里，没有额外分配；短字符串用 embstr，头和内容一次分配、内存连续；长字符串用 raw，头和内容分开分配。凯喵强调：这三种编码不是你选的，是…","c":{"lang":"bash","code":"SET n 12345\nOBJECT ENCODING n      # int\nSET s \"hello\"\nOBJECT ENCODING s      # embstr\nSET l \"a very long string exceeding forty four bytes......\"\nOBJECT ENCODING l      # raw"}},{"h":"现场 4：44 字节是 embstr 与 raw 的分界线","s":"embstr 只用于长度不超过 44 的字符串，超过就变 raw。这个数字不是随便定的，而是缓存行与对象头算出来的经验值。凯喵的实战经验：如果你有一批「刚好卡在四五十字节」的 key，稍微缩短命名或换哈希前缀，就能把它们从 raw 拉回…","c":null},{"h":"现场 5：append 让 embstr 悄悄变 raw","s":"embstr 设计成只读，一旦你对它 APPEND，Redis 必须先转成 raw 再改，编码当场变化且不可逆。凯喵见过有人拿 embstr 当计数器反复 append，结果编码一直停在 raw，内存比预期高。要累加数值用 INCR，要…","c":{"lang":"bash","code":"SET k \"abc\"\nOBJECT ENCODING k      # embstr\nAPPEND k \"def\"\nOBJECT ENCODING k      # raw（不可逆）"}},{"h":"现场 6：list 的演进：ziplist 到 quicklist","s":"老版本小 list 用 ziplist（一整块连续内存），大 list 用双向链表。后来统一成 quicklist：一个双向链表，每个节点是一块 listpack，兼顾内存连续与插入效率。凯喵提醒：quicklist 的节点大小由 li…","c":null},{"h":"现场 7：hash 在 listpack 与 hashtable 之间切换","s":"小 hash 用 listpack 紧凑存，字段数或单值长度超过阈值就转 hashtable。阈值由 hash-max-listpack-entries（默认 128）和 hash-max-listpack-value（默认 64）控制…","c":{"lang":"bash","code":"HSET user name kai age 3\nOBJECT ENCODING user   # listpack\n# 字段数超过 128 后\nOBJECT ENCODING user   # hashtable"}},{"h":"现场 8：set 的三态：intset、listpack、hashtable","s":"set 里全是整数且数量少时用 intset（有序整数数组，省内存）；元素是短字符串且数量少时用 listpack；否则用 hashtable。凯喵提醒：intset 只能存整数，一旦你往里加一个字符串，整个 set 会转成 hasht…","c":null},{"h":"现场 9：zset 的 listpack 与 skiplist","s":"小 zset 用 listpack 按分数有序存，元素数或值长度超阈值就转 skiplist 加字典。阈值是 zset-max-listpack-entries（默认 128）和 zset-max-listpack-value（默认 6…","c":null},{"h":"现场 10：渐进式 rehash 让扩容不卡顿","s":"字典扩容不是一次性搬完，而是保留新旧两张表，每次操作顺手搬一点，直到搬完。这就是渐进式 rehash。凯喵提醒：rehash 期间内存会短暂翻倍，如果你的实例内存已经贴着上限，一次大量写入可能直接触发淘汰甚至 OOM，扩容前留足余量是运…","c":{"lang":"bash","code":"# rehash 期间新旧表并存，内存短时上升\nINFO memory | grep used_memory"}},{"h":"现场 11：用 OBJECT ENCODING 现场排查","s":"怀疑内存异常时，先对可疑 key 跑 OBJECT ENCODING，再看 MEMORY USAGE。这两个命令能立刻告诉你它用的是哪种编码、实际占多少字节。凯喵的排查顺序：先定位大 key，再看编码是否「本该紧凑却变成了哈希表」，最后…","c":{"lang":"bash","code":"OBJECT ENCODING bigkey\nMEMORY USAGE bigkey SAMPLES 0"}},{"h":"现场 12：大 key 是内存与阻塞的双重炸弹","s":"单个 key 存了几十万个元素，不只是占内存，DEL 它时还会阻塞主线程。凯喵的规矩：大 key 用 UNLINK 异步删，设计阶段就按业务维度拆分，别让一个 key 无限膨胀。所谓「大」没有绝对标准，但超过几 MB 就该警惕，超过几十…","c":null},{"h":"现场 13：阈值参数的副作用不可逆","s":"把 hash-max-listpack-entries 调大能让更多 hash 留在紧凑编码，省内存，但单次操作要遍历整块内存，可能变慢；而且编码一旦转成 hashtable 就不会自动转回 listpack，改配置也救不回已经变胖的…","c":null},{"h":"现场 14：按访问模式选结构，而不是按直觉","s":"同样是「存一堆东西」，用 list、hash、set、zset 的内存与操作成本差别很大。凯喵的选型口诀：要按序取用 list，要按字段查 hash，要去重 set，要按分数排 zset。选错结构，后面所有的优化都是在给错误的地基打补丁…","c":null},{"h":"凯喵叮嘱：先观测，再判断，最后才优化","s":"最后叮嘱一句：排查内存问题前，先别急着加机器或调淘汰策略，先跑一遍 OBJECT ENCODING 和 MEMORY USAGE，把每个大 key 的编码与真实占用列出来。大多数所谓内存暴涨，其实就是某几个 key 悄悄换了编码、或者某…","c":null},{"h":"🧑‍💻 程序员视角","s":"Redis 不用 C 字符串而用 SDS：C 字符串取长度要 strlen 是 O(n)，且二进制不安全（遇 \\0 截断）。SDS 头部记录 len 与 alloc，取长度 O(1)、可存二进制、扩容有预分配策略。字符串有三种编码：短整…","c":null},{"h":"🎓 博士生视角","s":"Redis 的对象模型是「redisObject + 编码」：同一逻辑类型（string/list/hash/set/zset）按数据规模与内容切换底层编码（如 hash 在小规模时用 listpack，超阈值转 hashtable）…","c":null},{"h":"📚 考研者视角","s":"后端面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"SDS 相比 C 字符串的核心优势","stem":"关于 Redis 的 SDS（简单动态字符串），下列说法正确的是？ A. SDS 以 \\0 结尾，因此实现二进制安全 B. 获取字符串长度需要 O(n) 扫描 C. SDS 用 len 字段记录长度，获取长度 O(1) 且二进制安全 D. SDS 不支持预分配，每次修改都重新分配内存","opts":[{"k":"A","t":"SDS 以 \\0 结尾，因此实现二进制安全"},{"k":"B","t":"获取字符串长度需要 O(n) 扫描"},{"k":"C","t":"SDS 用 len 字段记录长度，获取长度 O(1) 且二进制安全"},{"k":"D","t":"SDS 不支持预分配，每次修改都重新分配内存"}],"ans":"C","why":"SDS 的二进制安全来自 len 字段（按字节数解析），而非 \\0 结尾；\\0 仅为兼容 C 函数。获取长度 O(1)；SDS 通过预分配与惰性释放减少重分配次数。"},{"kind":"output","q":"给定 SET 后 OBJECT ENCODING 的结果","stem":"依次执行： SET k1 123 SET k2 hello_world_12345678901234567890 OBJECT ENCODING k1 OBJECT ENCODING k2 其中 k2 的 value 长度为 30（≤44）。写出两条 OBJECT ENCODING 的输出。","opts":[],"ans":"int embstr","why":"整数可表示为 long → int 编码；长度 ≤44 的非整数短串 → embstr。均为紧凑编码。"},{"kind":"fix_error","q":"修正关于渐进式 rehash 的错误表述","stem":"某文档写道：「Redis 在扩容时会立刻把 ht[0] 的所有 entry 一次性搬移到 ht[1]，期间新写入仍落在 ht[0]。」 请指出错误并给出正确表述。","opts":[],"ans":"错误：不是一次性搬迁，也不是写入 ht[0]。正确：渐进式 rehash 用 rehashidx 记录进度，每次命令/定时任务搬一个桶；迁移期间新增 key 只写 ht[1]，查找需查 ht[0] 与 ht[1] 两张表，ht[0] 只减不增直至搬空后互换。","why":"渐进式 rehash 的核心是「分散搬运 + 迁移中写 ht[1]」，避免单线程一次性 rehash 导致的长尾延迟。"},{"kind":"coding","q":"LRU 缓存（LeetCode 146）","stem":"设计并实现一个满足 LRU(最近最少使用) 约束的数据结构：get/put 均 O(1)。详见原题，本题仅存元数据与链接，不搬运题面。","opts":[],"ans":"","why":"经典题：哈希表 + 双向链表（或 Python OrderedDict）实现 O(1) get/put；与本章 dict 双结构思想相通。"},{"kind":"coding","q":"设计 LRU 缓存结构（牛客 NC93）","stem":"设计 LRU 缓存，支持 set/get，容量满时淘汰最久未使用。详见原题，本题仅存元数据与链接，不搬运题面。","opts":[],"ans":"","why":"与 LeetCode 146 同构，考查哈希表 + 双向链表；注意牛客输入输出为函数调用式。"},{"kind":"coding","q":"实现 intset 升级判定","stem":"给定当前 intset 的 encoding 位宽（16/32/64）与一个待插入整数，判断是否需要升级（upgrade）以及升级后的目标位宽。写出判定函数并给出示例输出。","opts":[],"ans":"def need_upgrade(cur_bits, val): lo, hi = -(2(cur_bits-1)), 2(cur_bits-1)-1 if lo <= val <= hi: return cur_bits, False if -231 <= val <= 231-1: return 32, True…","why":"intset 升级按数值范围判断：超出当前位宽表示范围就必须升到能容纳的最小位宽（32 或 64），且升级单向不回退。"}],"works":[{"h":"把 SDS 的二进制安全归功于 \\0 结尾","d":"许多人以为「因为以 \\0 结尾所以能存任意字节」，恰恰相反：\\0 只是为兼容 C 库函数的副产物，二进制安全真正来自 len 字段（按字节数而非扫描 \\0 解析）。正确写法：回答「SDS 优点」时把「二进制安全」的解释锚定在 len 字段上，并说明保留 \\0 仅为复用 strlen 类 C 函数。"},{"h":"记错 Hash/ZSet/Set 编码切换的「且/或」关系","d":"实际条件是同时满足「元素数 ≤ 阈值」且「单值字节 ≤ 阈值」才保留紧凑编码（listpack/intset），任一不满足就转 hashtable/skiplist。正确写法：被问阈值时一律按「且」表述；排查「热 Hash 突然变 hashtable」优先查是否有某个 value 超过 hash-max-listpack-value=…"},{"h":"以为 embstr 是可原地修改的紧凑串","d":"embstr 是一次性分配、只读结构，任何 APPEND/INCR 都会先转成 RAW 再改，没有「原地扩容」。正确写法：高频写短串直接用 SET 覆盖或接受 embstr→raw 的转换；解释 44 字节分界时说明它来自 64B jemalloc 块减去 robj(16)+sdshdr8(3)+\\0(1)。"},{"h":"渐进式 rehash 期间仍向 ht[0] 写数据","d":"迁移进行中（rehashidx != -1）新增 key 只写 ht[1]，查找需查两张表，ht[0] 只减不增直至搬空。正确写法：描述 rehash 时明确「新增走 ht[1]、查找查两张表、搬完才互换」，避免写成「边搬边写旧表」。"},{"h":"intset 升级后还能降级","d":"intset 的 encoding 位宽升级（int16→int32→int64）是单向、不回退的，即使之后删掉大整数也不会缩回窄位宽。正确写法：答「intset 会升级但不会降级」，并说明升级是整块内存按新位宽重排，不是逐元素扩展。"},{"h":"用 ziplist 的「前驱长度字段」理解连锁更新","d":"旧 ziplist 用「前一 entry 长度」字段，长度从 1B 跨到 5B 会触发后续整段重编码（连锁更新）；Redis 7 换 listpack 改为「记录自身长度、从后向前遍历」以消除该问题。正确写法：被问「ziplist 缺陷」时答连锁更新，并补充 listpack 的修复思路，别把 ziplist 与 listpack 混…"},{"h":"线上用 KEYS 扫 key","d":"Redis 是单线程处理命令，KEYS 是 O(N) 全表遍历且阻塞：百万级 key 会让实例卡住数百毫秒到数秒，所有客户端一起超时，触发重试风暴。 用 SCAN 游标分批（每批 100~1000）；线上用 rename-command 直接屏蔽 KEYS / FLUSHALL / FLUSHDB。"},{"h":"用 ZRANGEBYSCORE 取出来再逐条 ZREM 删","d":"大集合下这是 N 次网络往返 + N 次单元素删除，延迟与网络放大几十倍，且中间态对并发读者可见。 用 ZREMRANGEBYSCORE / ZREMRANGEBYRANK 一条命令批量删；跨结构迁移用 ZUNIONSTORE（WEIGHTS 0）落到新 key 再 DEL 旧的。"}],"asks":[{"q":"Redis 的 String 为什么有 int、embstr、raw 三种编码？44 字节的分界是怎么来的？","a":"Redis 按内容与长度选编码以省内存： - 可表示为 long 的整数 → int（数值直接存进 redisObject.ptr，不另开 buf）； - 长度 ≤44 的非整数短串 → embstr（robj 与 sds 一次性分配，只读紧凑）； - 其余 → raw（两次分配，可修改）。 44 字节来自 64B jemalloc 最小块：64 - robj(16) - sdshdr8(3) -…","fu":["embstr 能原地修改吗？为什么？","SET k 123 后 APPEND k 'x'，OBJECT ENCODING 如何变化？"],"tag":"通用/字节"},{"q":"ZSet 为什么用跳表而不是红黑树？底层还配了什么结构？","a":"ZSet 在元素较多时用「skiplist + dict」双结构： - 跳表按 score 排序，支持 ZRANGEBYSCORE 等范围查询，查找 O(log n)，实现简单、范围遍历自然；每层以 1/4 概率晋升，最大 32 层。 - dict 按 member 查 score，O(1)（如 ZSCORE），与跳表共享同一份 member/score 对象，避免重复存储。 相比红黑树，跳表范围…","fu":["跳表层数怎么决定？期望层数是多少？","listpack 与 skiplist 的转换条件？"],"tag":"通用/腾讯"},{"q":"说一下 Redis 的 dict 渐进式 rehash 过程，为什么这样设计？","a":"dict 用 ht[0]/ht[1] 两张表。负载因子 ≥1（或 ≥5 强制）扩容、<0.1 缩容，size 取 2 的幂以便位运算取模。 渐进式 rehash：用 rehashidx 记录进度，不在一次命令里搬完，而是分散到每次增删改查及 serverCron（连搬 100 桶/1ms 上限）。迁移期间：新增 key 只写 ht[1]，查找要查两张表，ht[0] 只减不增，搬完把 ht[1] 换…","fu":["rehash 期间新写入落在哪张表？","缩容的触发条件是什么？"],"tag":"通用/拼多多"},{"q":"ziplist 有什么缺陷？Redis 7 用什么替代它，解决了什么问题？","a":"ziplist 用「前一 entry 长度」字段（1B 或 5B）定位前驱。当某个 entry 长度从 <254 变 ≥254 时，其「前驱长度」从 1B 进位到 5B，可能导致后续连续 entry 的该字段接连进位，引发连锁更新（cascade update），最坏 O(n²) 重编码。 Redis 7 用 listpack 替代：改为「记录本 entry 自身长度」并从后向前遍历，删除对前驱长…","fu":["连锁更新的触发条件是什么？","listpack 如何从后向前解析？"],"tag":"通用/阿里"}]},{"id":"mw-ch02","subj":"middleware","title":"Redis 持久化与内存管理","summary":"RDB 的 fork + 写时复制与快照时机；AOF 的 appendfsync 三策略与重写机制；混合持久化；过期键的惰性删除与定期删除；八种内存淘汰策略与 maxmemory 的选型；内存碎片与 big key 排查。","concepts":[{"id":"mw-ch02/01-rdb-fork-cow","file":"01-rdb-fork-cow.md","title":"一、RDB 快照：fork 与写时复制（COW）","kind":"flow","secs":[{"h":"① RDB 快照与 fork + 写时复制（COW）","s":"（中立陈述）RDB 是 Redis 某一时刻内存数据的二进制全量快照。生成方式有 SAVE（主进程阻塞）与 BGSAVE（fork 子进程后台生成）。BGSAVE 的核心在于 fork() 系统调用：子进程与父进程共享同一份物理内存页…","c":null},{"h":"② save m n：RDB 的自动触发规则","s":"（中立陈述）redis.conf 中的 save m n 表示「在 m 秒内发生了至少 n 次修改，则触发一次 BGSAVE」。可配置多条规则，任意一条满足即触发。还有 stop-writes-on-bgsave-error、rdbco…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"class KV:\n    def __init__(self):\n        self.data = {f\"k{i}\": i for i in range(5)}\n    def fork_snapshot(self):\n        # 模拟 COW：子进程拿到 fork 时刻的只读视图（浅拷贝共享页）\n        return dict(self.data)\n\ndb = KV()\nprint(\"BGSAVE 触发，fork 子进程生成 RDB 快照\")\n…"}}]},{"id":"mw-ch02/02-aof-appendfsync-rewrite","file":"02-aof-appendfsync-rewrite.md","title":"二、AOF 持久化：追加日志、fsync 策略与重写","kind":"flow","secs":[{"h":"① AOF 追加与 appendfsync 三策略","s":"（中立陈述）AOF（Append Only File）以写命令日志形式持久化：每执行一条写命令，就将其协议格式追加到 AOF 缓冲区，再按 appendfsync 策略刷盘。三种策略：always（每条命令 fsync）、everyse…","c":null},{"h":"② AOF 重写（rewrite）与混合持久化","s":"（中立陈述）AOF 会随写命令无限膨胀（如对一个 key 反复 SET）。BGREWRITEAOF / 自动 auto-aof-rewrite-percentage+auto-aof-rewrite-min-size 触发重写：fork…","c":null}]},{"id":"mw-ch02/03-expire-eviction-memory","file":"03-expire-eviction-memory.md","title":"三、过期删除、内存淘汰与碎片管理","kind":"stack","secs":[{"h":"① 过期键删除：惰性删除 + 定期删除","s":"（中立陈述）给 key 设置 TTL 后，Redis 不会在到期瞬间自动删除，而是用两种策略配合：①惰性删除（lazy expiration）——访问 key 时检查是否过期，过期则删除并返回空；②定期删除（active expire）…","c":null},{"h":"② 内存淘汰、maxmemory 与碎片管理","s":"（中立陈述）当 used_memory 达到 maxmemory 且再写入时，Redis 按 maxmemory-policy 选 key 淘汰。八种策略分三类：noeviction（默认，写满报错）、lru（近似 LRU，allkey…","c":null}]},{"id":"mw-ch02/04-redis-practical-recipes","file":"04-redis-practical-recipes.md","title":"§4 mw-ch02 实战手记：凯喵带你把 Redis 用「崩」","kind":"flow","secs":[{"h":"现场一：忽略 RDB fork 的 COW 放大，被 OOM kill","s":"凯喵在主库跑 bgsave，期间大量写入触发 copy-on-write 复制页，RSS 接近翻倍，撞上容器内存上限被 OOM kill，恢复又要重放 AOF。解法：单实例内存控在物理内存一半内；关 THP（transparent_hu…","c":{"lang":"bash","code":"# 关掉透明大页，减小 fork 时 COW 页大小\necho never > /sys/kernel/mm/transparent_hugepage/enabled"}},{"h":"现场二：AOF 用 always 把吞吐打到地板","s":"凯喵为「绝不丢数据」把 appendfsync always，每条写都 fsync，QPS 从 10 万掉到几千。always 每条刷盘，everysec 每秒一批，折中且最多丢 1 秒。绝大多数场景用 everysec。","c":{"lang":"conf","code":"# redis.conf\nappendonly yes\nappendfsync everysec   # ✅ 每秒 fsync，最多丢 1s，吞吐可接受\n# appendfsync always  # ❌ 每条刷盘，性能灾难"}},{"h":"现场三：bigkey 一把删，主线程卡死","s":"凯喵 DEL 一个 500 万字段的 hash，主线程阻塞好几秒，所有请求超时。大 key 的删除/遍历要分批：UNLINK（异步惰性删）或 HSCAN 分批清，别一把梭。","c":{"lang":"bash","code":"# ✅ 异步删除，不阻塞主线程\nUNLINK big_hash\n# 遍历大 key 分批处理\nHSCAN big_hash 0 COUNT 1000"}},{"h":"现场四：热点 key 打爆单线程，CPU 100%","s":"凯喵某个 key 被疯狂访问，Redis 单线程处理不过来，整体变慢。热点 key 要：本地缓存挡一层、key 加随机后缀分片、或读多写少场景上从节点分担读。","c":{"lang":"java","code":"// 热点 key 加随机后缀拆成多个，分散单线程压力\nString k = \"hot:\" + (threadId % 10);"}},{"h":"现场五：内存淘汰策略配错，该清的没清","s":"凯喵设了 maxmemory 却用默认 noeviction，内存满了写请求直接报错而不是淘汰。按业务选策略：缓存用 allkeys-lru，保留 TTL 语义用 volatile-lru。","c":{"lang":"conf","code":"maxmemory 4gb\nmaxmemory-policy allkeys-lru   # ✅ 内存满按 LRU 淘汰\n# noeviction                   # ❌ 满了直接拒绝写入"}},{"h":"现场六：过期键没及时删，内存悄悄涨","s":"凯喵以为设了 TTL 就万事大吉，结果大量 key 集中过期时 Redis 才被动清理，内存短时涨、访问时卡。主动过期有定时+惰性两种，集中过期会阻塞；用随机过期时间打散（TTL + 随机抖动）。","c":{"lang":"bash","code":"# ❌ 几百万 key 同一秒过期，集中清理阻塞\nEXPIRE k 3600\n# ✅ 加随机抖动打散\nEXPIRE k 3600 + rand(0, 600)"}},{"h":"现场七：把 Redis 当持久数据库，重启数据没了","s":"凯喵把订单状态只放 Redis 不设持久化，主节点故障切换后数据全丢。Redis 是缓存/存储但默认 RDB 是周期快照，可能丢间隔内数据。重要数据双写数据库，或开 AOF+副本。","c":{"lang":"conf","code":"# 重要数据至少开 AOF，并配副本\nappendonly yes\n# 另加从节点，主挂从接\nreplicaof <masterip> <masterport>"}},{"h":"现场八：keys 在生产环境一键卡死","s":"凯喵为查 key 在线上跑 KEYS ，几百万 key 一次性遍历，主线程卡几十秒。生产一律用 SCAN 游标迭代，分批返回，不阻塞。","c":{"lang":"bash","code":"# ✅ 分批游标，安全\nSCAN 0 MATCH \"order:*\" COUNT 1000\n# ❌ KEYS * 全量遍历，生产禁用"}},{"h":"现场九：Pipeline 没用，网络往返把延迟堆高","s":"凯喵循环发 1000 条命令，每条等回包，延迟 ×1000。多条命令打包用 Pipeline 一次网络往返，吞吐翻几十倍；需要原子性用 MULTI/EXEC 事务。","c":{"lang":"java","code":"// ✅ Pipeline 合并往返\nPipeline p = jedis.pipelined();\nfor (String k : keys) p.get(k);\np.sync();"}},{"h":"现场十：Hash 的 field 过多变成 bigkey","s":"凯喵把「全站用户在线状态」塞进一个 hash 的几百万 field，单 key 巨大，迁移/删除都卡。超大集合要按业务分片成多个 key（如 online:{shard}），控制单 key 规模。","c":{"lang":"bash","code":"# ❌ 一个 hash 装百万 field\nHSET online_all user1 1\n# ✅ 按分片拆\nHSET online:0 user1 1   # 按 hash(uid)%N 分片"}},{"h":"现场十一：Lua 脚本太长，阻塞且无法迁移","s":"凯喵写了个百行 Lua 脚本做复杂事务，执行期间主线程全卡，集群迁移也因脚本无法跨 slot 失败。Lua 脚本要短平快、只操作同 slot 的 key，复杂逻辑放到客户端。","c":{"lang":"lua","code":"-- ✅ 短脚本，同 slot\nredis.call(\"SET\", KEYS[1], ARGV[1])\nredis.call(\"EXPIRE\", KEYS[1], ARGV[2])"}},{"h":"现场十二：maxmemory 不设，机器内存被打满","s":"凯喵的 Redis 没配 maxmemory，缓存越涨越多直到 OS 杀进程。Redis 不背「内存上限」的责任，必须显式设 maxmemory + 淘汰策略，否则迟早 OOM。","c":{"lang":"conf","code":"maxmemory 8gb\nmaxmemory-policy volatile-ttl   # 优先淘汰快过期的"}},{"h":"现场之外：凯喵的 Redis 三道防线","s":"线上用 Redis，凯喵给自己立了三道防线。第一道是容量线：任何单实例内存都不许超过物理内存一半，fork 时的 COW 放大和 AOF 重写都要预留空间，绝不赌它不触发。第二道是慢操作线：禁止 KEYS、禁止一把 DEL 大 key…","c":null},{"h":"现场拾遗：监控与容量才是最后的保险","s":"最后凯喵强调，光靠编码规范还不够，Redis 必须配监控。内存使用率、命中率、fork 耗时、慢查询日志这几个指标要进告警面板，容量到七成就要扩容或清理。很多事故不是代码写错，而是没人发现内存曲线悄悄爬到上限。把容量和延迟当成一等公民来…","c":null},{"h":"一句话收尾","s":"凯喵最后提醒：Redis 再快也只是内存里的键值库，它解决的是「快」而不是「可靠」。任何你承受不起丢失的数据，都不该只活在 Redis 里。把它的角色摆正——缓存加速可以，做唯一真相源不行——这才是所有避坑清单背后真正要懂的那一句话。","c":null},{"h":"🧑‍💻 程序员视角","s":"RDB 的 fork 在写时复制下会放大内存：主库写入频繁时，被修改的页要复制一份，峰值内存可能是两倍——在内存吃紧的机器上做 bgsave 直接把实例打挂。AOF 用 always 每条命令都 fsync，吞吐掉到几百 QPS，生产一…","c":null},{"h":"🎓 博士生视角","s":"Redis 的单线程指的是「命令执行单线程」，网络 IO 在 6.0 后可以多线程。这一设计把「并发安全」问题消掉，代价是「任何慢命令都会阻塞所有人」——所以 KEYS 、大 DEL、复杂 ZRANGE 都是生产禁忌。持久化的两难是「性…","c":null},{"h":"📚 考研者视角","s":"后端面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"RDB 的 BGSAVE 为什么用 fork + 写时复制","stem":"关于 Redis 的 RDB 快照与 BGSAVE，下列说法正确的是？ A. BGSAVE 在主线程直接全量拷贝内存，生成快照 B. BGSAVE 通过 fork 子进程 + 写时复制(COW) 生成快照，仅被修改的页才复制 C. COW 保证了 RDB 不丢数据，两次快照之间宕机也能恢复 D. SAVE 和 BGSAVE 都会阻塞主线程","opts":[{"k":"A","t":"BGSAVE 在主线程直接全量拷贝内存"},{"k":"B","t":"BGSAVE 用 fork + COW，仅修改页才复制"},{"k":"C","t":"COW 保证 RDB 不丢数据"},{"k":"D","t":"SAVE 与 BGSAVE 都阻塞主线程"}],"ans":"B","why":"BGSAVE fork 子进程，父子共享页、写时复制仅复制被修改页，开销为 O(页表) 而非 O(数据量)；COW 只是降低快照成本，RDB 仍是点快照，间隔数据会丢失；SAVE 阻塞、BGSAVE 不阻塞主线程。"},{"kind":"output","q":"appendfsync 三策略的耐久性与性能排序","stem":"请按「耐久性从强到弱」与「吞吐从高到低」分别排序：always / everysec / no（默认策略）。","opts":[],"ans":"耐久性: always > everysec > no 吞吐: no > everysec > always","why":"always 每条命令 fsync 最安全最慢；everysec 每秒 fsync 默认，最多丢约 1 秒；no 只写缓冲由 OS 刷盘最快最不安全。两个排序恰好相反。"},{"kind":"fix_error","q":"修正关于 save m n 的错误表述","stem":"某文档写道：「save 900 1、save 300 10、save 60 10000 三条规则必须同时满足才会触发 BGSAVE，触发后每条规则各自存一份快照。」 请指出错误并给出正确表述。","opts":[],"ans":"错误：三条规则不是“且”而是“或”关系，任一满足即触发；且只会生成一份 RDB 快照（触发后重置 dirty 计数与 lastsave 时间戳），不是每条规则各存一份。正确：m 秒内发生至少 n 次修改即触发一次 BGSAVE。","why":"save m n 三条规则是「或」关系：任意一条满足即触发一次 BGSAVE，不是「且」、也不会每条各存一份。BGSAVE 触发后重置脏页计数与 lastsave 时间戳，只生成一份 RDB 快照。理解这点才能正确估算快照频率与数据丢失窗口。"},{"kind":"coding","q":"LRU 缓存（LeetCode 146）","stem":"设计并实现一个满足 LRU(最近最少使用) 约束的数据结构：get/put 均 O(1)。详见原题，本题仅存元数据与链接，不搬运题面。","opts":[],"ans":"","why":"经典题：哈希表 + 双向链表（或 Python OrderedDict）实现 O(1) get/put；与本章「近似 LRU」思想相通——Redis 用随机采样近似以降低维护开销，本题则要求严格 LRU。"},{"kind":"coding","q":"LFU 缓存（LeetCode 460）","stem":"设计并实现 LFU(最不经常使用) 缓存，get/put 均 O(1)，按访问频次淘汰最低频者，频次相同淘汰最久未用。详见原题，仅存元数据与链接。","opts":[],"ans":"","why":"与本章「近似 LFU」对应：LeetCode 要求严格 O(1) LFU（频率桶 + 双向链表 + 最小频链表头），而 Redis 用「对数计数器 + 衰减 + 随机采样」近似以省开销。"},{"kind":"choice","q":"mem_fragmentation_ratio 的含义与异常处置","stem":"关于 mem_fragmentation_ratio = used_memory_rss / used_memory，下列说法正确的是？ A. 比值越小于 1 说明碎片越少、越健康 B. 比值 > 1.5 表示内存碎片严重，可考虑 activedefrag 或重启 C. 比值 < 1 说明内存充足、无碎片 D. 该比值只反映逻辑内存，与 OS 无关","opts":[{"k":"A","t":"比值越小于 1 越健康"},{"k":"B","t":"比值>1.5 碎片严重，可 activedefrag/重启"},{"k":"C","t":"比值<1 说明内存充足无碎片"},{"k":"D","t":"只反映逻辑内存，与 OS 无关"}],"ans":"B","why":"ratio>1.5 表示碎片多（正常略大于 1）；ratio<1 说明 rss 小于逻辑内存，是部分内存被 OS 换页到 swap 的危险信号，性能会骤降，绝非健康。"}],"works":[{"h":"以为 fork + COW 等于“数据不丢”","d":"COW 只保证子进程拿到 fork 时刻的一致性快照，降低的是快照开销；RDB 仍是定期点快照，两次快照之间崩溃会丢失间隔数据。正确写法：回答 RDB 持久性时明确「快照点之前可恢复、快照点之后丢失」，不把 COW 当成不丢数据的安全机制。"},{"h":"把 no 策略理解成“不写文件”","d":"appendfsync no 仍是每条写命令追加进 AOF 文件（写入内核 page cache），只是不主动 fsync；进程崩溃数据尚在缓冲可恢复，但主机断电会丢失未刷盘部分且量不可控。正确写法：称其为「只写缓冲、由 OS 决定刷盘」，并说明它最不安全、绝不适用于来源唯一的数据。"},{"h":"混淆 AOF 重写与“压缩旧文件”","d":"重写是 fork 子进程读取当前内存，生成能重建现状的最小命令集写入新文件，再原子替换旧文件；重写期间旧 AOF 仍在增长。正确写法：磁盘需预留约 2 倍空间，并说明重写后体积由 O(操作数) 降到 O(当前数据量)，而非原地压缩。"},{"h":"认为过期 key 到期会“立刻自动删除”","d":"Redis 用惰性删除（访问时删）+ 定期删除（周期性随机采样删）配合，是概率性、非全量的；大量 key 同时过期且长期无人访问会暂占内存。正确写法：给 TTL 加随机抖动避免集中过期，并理解过期删除不生成 del 命令、主从靠主节点传播 del 同步。"},{"h":"以为 Redis 用的是严格 LRU/LFU","d":"Redis 不维护全局访问链表，而是随机采样 maxmemory-samples（默认 5）个候选、从中挑最久未用/最低频的淘汰，是近似算法。正确写法：答「近似 LRU/LFU（随机采样）」，并说明其在命中率接近的前提下大幅降低维护开销，是单线程低延迟的取舍。"},{"h":"把 mem_fragmentation_ratio < 1 当成“碎片好”","d":"该比值 = used_memory_rss / used_memory；>1 才表示有碎片（正常略大于 1，>1.5 需治理），<1 说明物理常驻小于逻辑内存，是部分内存被 OS 换页到 swap，属危险信号而非健康。正确写法：ratio<1 要立刻排查 swap，而非欣喜于“碎片低”。"},{"h":"appendfsync everysec 却承诺「零丢失」","d":"everysec 是「每秒后台 fsync 一次」，宕机最多丢约 1 秒写入；no 由 OS 决定（可能丢几十秒）；只有 always 才接近零丢失，但吞吐会掉一个量级。 按 RPO 选：能接受秒级丢失用 everysec（多数场景的默认答案）；不能接受就 always + 独立盘，或 everysec + 主从 + WAIT 确认副…"},{"h":"设了 maxmemory 但没设淘汰策略","d":"默认策略是 noeviction：内存打满后写命令直接报错（OOM command not allowed），读还能用——监控上看着「服务还在」，业务侧却全线写失败。 纯缓存用 allkeys-lru / allkeys-lfu；要保数据用 volatile- 并确保 key 都有 TTL；同时盯 evicted_keys 与 use…"}],"asks":[{"q":"RDB 和 AOF 的区别是什么？生产环境一般怎么选？","a":"RDB：二进制全量快照，文件小、恢复快，但两次快照间崩溃会丢数据；生成靠 BGSAVE 的 fork + 写时复制，开销为 O(页表)。 AOF：写命令日志，可配置 always(不丢)/everysec(丢约1秒,默认)/no(不可控)；恢复靠重放，更耐久但文件大、恢复慢；靠 rewrite 压缩。 生产建议：两者同时开启——用 AOF 保证耐久（默认 everysec + 混合持久化），RDB…","fu":["BGSAVE 的 fork 为什么可能阻塞主线程？COW 期间内存为什么可能翻倍？","AOF 重写期间磁盘要预留多少空间？为什么？"],"tag":"通用/字节"},{"q":"Redis 的内存淘汰策略有哪些？为什么用近似 LRU 而不是严格 LRU？","a":"八种：noeviction(默认写满报错)、allkeys-lru/volatile-lru、allkeys-lfu/volatile-lfu、allkeys-random/volatile-random、volatile-ttl；allkeys- 对所有 key，volatile- 仅对带 TTL 的 key 生效。 近似而非严格 LRU：严格 LRU 需维护全局访问时序链表，每次访问改链表、淘…","fu":["maxmemory-samples 调大有什么影响？","volatile-lru 和 allkeys-lru 在业务上怎么选？"],"tag":"通用/腾讯"},{"q":"Redis 的 key 过期了会立刻删除吗？过期删除和内存淘汰是什么关系？","a":"不会立刻删除。采用惰性删除（访问时检查并删除）+ 定期删除（serverCron 每秒约 10 次，随机采样带 TTL 的 key 删过期的，过期比例超 25% 则继续本轮直到超时上限）配合：惰性省 CPU、定期保回收。 与淘汰的关系：过期删除针对「带 TTL 且到期」的 key；内存淘汰（maxmemory-policy）针对「内存达到 maxmemory 再写入」时按策略选 key 淘汰，两者…","fu":["定期删除为什么抽样而不是全量扫描？","大量 key 同时过期但无人访问会怎样？怎么避免？"],"tag":"通用/拼多多"},{"q":"AOF 重写（rewrite）是什么？为什么能缩小体积？混合持久化解决了什么问题？","a":"重写：fork 子进程读取当前内存，直接生成“能重建现状的最小命令集”（如把 100 次 INCR 压成最终 SET、丢弃已过期/已删除的冗余命令），写入新 AOF，再把重写期间的增量写命令追加其后，最后原子 rename 替换旧文件。 体积缩小：命令日志从 O(操作数) 降到 O(当前数据量)。 混合持久化：Redis 4+ 支持 aof-use-rdb-preamble yes——重写文件以…","fu":["重写期间旧 AOF 还在增长吗？磁盘要预留多少？","重写和 BGSAVE 的 fork+COW 有什么关系？"],"tag":"通用/阿里"}]},{"id":"mw-ch03","subj":"middleware","title":"Redis 高可用：主从、哨兵与 Cluster","summary":"主从复制的全量同步与增量同步（psync、repl_backlog）；哨兵的主观/客观下线与 Raft 选主、故障转移流程；Cluster 的 16384 槽位、CRC16 分片与 MOVED/ASK 重定向；集群下的多 key 操作限制…","concepts":[{"id":"mw-ch03/01-master-slave-replication","file":"01-master-slave-replication.md","title":"一、主从复制：全量同步与部分同步","kind":"flow","secs":[{"h":"① 全量同步 PSYNC：首次或无法续传时的 RDB 传输","s":"（中立陈述）从节点启动或断线过久后，向主节点发送 PSYNC ? -1（首次）或 PSYNC <replid> <offset>（带历史）。主节点若支持部分同步且 backlog 仍保留对应偏移，则回 CONTINUE 走增量；否则回…","c":null},{"h":"② 部分同步 repl_backlog、offset 与心跳 REPLCONF ACK","s":"（中立陈述）主从建立连接后进入命令传播阶段：主节点每执行一条写命令，就把命令与新的 offset 追加进 repl_backlog 并发送给从节点；从节点执行后推进自己的 offset，并周期性发 REPLCONF ACK <offse…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"print(\"=== 主从全量同步 PSYNC 模拟 ===\")\nmaster_data = {\"k1\": 100, \"k2\": 200, \"k3\": 300}\nprint(\"主节点数据:\", master_data)\nprint(\"从节点 -> 主节点: PSYNC ? -1 (首次, 请求全量)\")\nsnapshot = dict(master_data)\nprint(\"主节点 fork 子进程生成 RDB 快照:\", snapshot)\nslave_data = dict(snapshot)\nprint(\"从节点清空本地并载入 RDB -> 数据:\", slave_data)\nmaster_data[\"k4\"] = 400\n…"}}]},{"id":"mw-ch03/02-sentinel","file":"02-sentinel.md","title":"二、哨兵（Sentinel）：故障发现与故障转移","kind":"flow","secs":[{"h":"① 主观下线 SDOWN 与客观下线 ODOWN（quorum 投票）","s":"（中立陈述）每个哨兵独立地以 down-after-milliseconds 为阈值：若在该时间内没收到主节点的有效心跳（PING 未回 PONG/LOADING/MASTERDOWN），该哨兵单方面认定主节点「主观下线（SDOWN）」…","c":null},{"h":"② Raft 式 leader 选举与故障转移的选主规则","s":"（中立陈述）主节点进入 ODOWN 后，哨兵集群需要从多个哨兵中选出一个「leader 哨兵」来实际执行故障转移（避免多个哨兵同时执行造成混乱）。选举采用类似 Raft 的「先到先得 + 任期（epoch）+ 多数派」机制：每个哨兵在发…","c":null}]},{"id":"mw-ch03/03-cluster","file":"03-cluster.md","title":"三、Redis Cluster：分片、重定向、槽迁移与脑裂防护","kind":"flow","secs":[{"h":"① 16384 槽位、CRC16 键槽计算与 MOVED/ASK 重定向","s":"（中立陈述）Redis Cluster 把整个键空间划分为 16384 个哈希槽（slot），每个 key 通过 slot = CRC16(key) & 16383 落到某个槽，槽再被分配给各主节点（每主负责一段连续或离散的槽）——这就…","c":null},{"h":"② 槽迁移（resharding）与集群总线 gossip","s":"（中立陈述）集群扩缩容/负载均衡靠槽迁移：用 CLUSTER SETSLOT <slot> IMPORTING/MIGRATING 标记源/目标节点，再用 MIGRATE 逐 key 把数据从源搬到目标；迁移期间对「已归属目标但尚未搬走…","c":null},{"h":"③ 脑裂（split-brain）与 min-replicas 防护","s":"（中立陈述）脑裂指网络分区导致原主节点与多数从节点/哨兵失联，但从节点侧哨兵选出新主继续服务——分区恢复后旧主「复活」，造成「双主」、数据分裂与丢失。Redis 用 min-replicas-to-write + min-replica…","c":null}]},{"id":"mw-ch03/04-redis-ha-practical-recipes","file":"04-redis-ha-practical-recipes.md","title":"Redis 高可用实战手记：凯喵经历的一次主从切换灾难","kind":"flow","secs":[{"h":"开场：高可用不等于「不出故障」","s":"很多人以为上了哨兵就「不会挂」。实际的高可用只保证一件事：故障发生时，服务能在可接受的时间内自动恢复。它不保证不丢数据、不保证不短暂不可用、更不保证不出错。","c":{"lang":"text","code":"repl-backlog-size     复制积压缓冲区大小（默认 1MB，生产建议 64MB~256MB）\nrepl-diskless-sync    yes 时不落盘，直接通过网络传 RDB（省磁盘 IO）\nrepl-diskless-sync-delay  延迟几秒再开始，让多个从库一起等，避免重复 fork\nclient-output-buffer-limit replica  从库缓冲区上限，超了会断开从库"}},{"h":"收尾：凯喵的高可用三问","s":"每次设计或复盘 Redis 高可用，先回答三个问题：","c":null}]}],"exams":[{"kind":"choice","q":"主从复制中全量同步与部分同步的触发条件","stem":"关于 Redis 主从复制，下列说法正确的是？ A. 从节点每次重连都会触发全量同步（FULLRESYNC） B. 从节点断线重连时，只要断线期间写命令仍在主节点 repl_backlog 窗口内，就走部分同步只补缺失区间 C. repl_backlog 是无限增长的缓冲，永远不会被覆盖 D. REPLCONF ACK 只用于 TCP 心跳，与复制进度无关","opts":[{"k":"A","t":"每次重连都全量同步"},{"k":"B","t":"backlog 窗口内重连走部分同步"},{"k":"C","t":"repl_backlog 无限增长"},{"k":"D","t":"REPLCONF ACK 只做 TCP 心跳"}],"ans":"B","why":"从节点断线重连时若上报的 offset 仍在 repl_backlog 窗口内则走部分同步（CONTINUE）只补缺失区间；只有首次/换主/窗口被覆盖才 FULLRESYNC。repl_backlog 是固定大小环形缓冲会被覆盖；REPLCONF ACK 上报的是复制 offset，用于计算 lag 与 min-replicas 保护。"},{"kind":"choice","q":"哨兵 quorum 与 leader 选举多数派的区别","stem":"关于 Redis 哨兵，下列说法正确的是？ A. ODOWN 需要「多数派（>N/2）」哨兵确认，quorum 必须等于 N/2+1 B. quorum 是确认主节点 SDOWN 的哨兵数门槛，用于达成 ODOWN，通常小于哨兵总数 C. 故障转移由所有哨兵同时执行，无需选 leader D. SDOWN 自动等同于 ODOWN","opts":[{"k":"A","t":"ODOWN 需多数派，quorum=N/2+1"},{"k":"B","t":"quorum 是确认下线门槛，通常 < 总数"},{"k":"C","t":"所有哨兵同时执行故障转移"},{"k":"D","t":"SDOWN 自动等同 ODOWN"}],"ans":"B","why":"quorum 只是「确认 SDOWN 的哨兵数门槛」用于达成 ODOWN，不要求多数派、通常小于哨兵总数；真正执行故障转移的 leader 选举才需要 >N/2 多数派。SDOWN 是单哨兵主观判定，需经 is-master-down-by-addr 投票累计到 quorum 才变 ODOWN，且由选出的 leader 执行转移。"},{"kind":"choice","q":"Cluster 的 MOVED 与 ASK 重定向区别","stem":"Redis Cluster 中，关于 MOVED 与 ASK，下列说法正确的是？ A. MOVED 与 ASK 都会让客户端刷新本地槽→节点映射 B. MOVED 表示槽归属已永久变更，客户端应刷新映射；ASK 仅发生在迁移中间态，本次临时重定向、不刷新映射 C. ASK 表示槽归属已永久变更，MOVED 是临时重定向 D. 二者都只在跨槽多 key 时出现","opts":[{"k":"A","t":"二者都刷新映射"},{"k":"B","t":"MOVED 刷新、ASK 不刷新"},{"k":"C","t":"ASK 刷新、MOVED 临时"},{"k":"D","t":"只在跨槽多 key 出现"}],"ans":"B","why":"MOVED 表示槽归属已永久变更，客户端应刷新本地映射；ASK 仅发生在槽迁移中间态，是本次临时重定向、不刷新映射，等迁移完成收到 MOVED 才更新。二者都出现在单 key 路由错误/迁移场景，与跨槽多 key 的 CROSSSLOT 限制无关。"},{"kind":"output","q":"Cluster 选新主的优先级排序","stem":"Redis Cluster / 哨兵故障转移选新主时，依次按什么规则排序？（写出顺序与方向）","opts":[],"ans":"1) replica-priority 最小优先 2) 复制 offset 最大（数据最新）优先 3) runid 字典序最小优先","why":"故障转移选新主按三层优先级：① replica-priority 最小优先（可手动调权）；② 复制 offset 最大（数据最新）优先；③ runid 字典序最小优先（兜底确定性）。三者依次比较，前一层相等才进入下一层，保证结果唯一且可复现。"},{"kind":"coding","q":"一致性哈希（Consistent Hashing，LeetCode 设计题思路）","stem":"设计并实现一个一致性哈希结构，支持 addNode/removeNode/ getNode(key)，使节点增减时只有少量 key 需要重新映射。详见原题，本题仅存元数据与链接，不搬运题面。与本章「Cluster 固定 16384 槽」思想相通——都是减少重分片成本的路由策略。","opts":[],"ans":"","why":"一致性哈希用「哈希环 + 虚拟节点」把 key 与节点映射到同一环上，节点增减只影响环上相邻区间的 key；与 Cluster 的「固定 16384 槽 + 槽→节点映射」异曲同工——二者都把『重分片影响范围』从 O(N) 降到局部。"},{"kind":"coding","q":"LFU 缓存（LeetCode 460，与 repl_backlog 频率思想对比）","stem":"设计并实现 LFU(最不经常使用) 缓存，get/put 均 O(1)，按访问频次淘汰最低频者，频次相同淘汰最久未用。详见原题，仅存元数据与链接。与本章「复制偏移量/频率统计」不同，但都体现了「用计数刻画热度」的思想。","opts":[],"ans":"","why":"严格 O(1) LFU（频率桶 + 双向链表 + 最小频链表头）；Redis 自身用对数计数器+衰减+随机采样近似 LFU 省开销。本题训练「用计数/频率做淘汰」的建模能力，与高可用章节的「统计类机制」思维互补。"},{"kind":"coding","q":"分布式选主 / Raft 相关笔试题（牛客）","stem":"牛客网分布式/Redis 高频笔试题：给定若干节点心跳与 epoch，模拟选出 leader 的过程。详见原题，仅存元数据与链接，不搬运题面。与本章「哨兵类 Raft 选举（epoch + 多数派）」直接对应。","opts":[],"ans":"","why":"牛客常考「类 Raft 选主」：epoch 任期递增、先到先得、拿到 >N/2 票当选、旧任期选票作废。与哨兵 leader 选举机制一致，是分布式共识的入门建模题。"},{"kind":"explain","q":"主从切换为什么会丢数据，min-replicas 如何把「静默丢失」变成「显式失败」","stem":"请解释： 1. Redis 主从复制在故障转移时，丢失的写入是哪一部分？为什么无法完全避免？ 2. min-replicas-to-write 与 min-replicas-max-lag 分别限制什么？开启后故障表现会怎么变化？ 3. 为什么说「宁可短暂不可写，也不要接受一个已经和数据流断开的主库继续接写」？","opts":[],"ans":"1) 丢的是「主库已确认写入、但尚未传播到从库」的那一段。复制是异步的：主库写内存后立刻返回成功，再异步通过 replication backlog 发给从库。主库此刻崩溃/被判定下线时，backlog 中未送达的部分就永久丢失。无法完全避免，因为同步复制（等所有从库确认）会把写延迟抬到网络 RTT 量级，与 Redi…","why":"考点：异步复制的 RPO、两个 min-replicas 参数的语义、以及「可观测的失败优于不可观测的丢失」。"}],"works":[{"h":"混淆全量同步与部分同步、以为从节点重启一定走全量","d":"从节点断线重连时若断线期间写命令仍在主节点 repl_backlog 环形缓冲窗口内（offset 未滑出），走「部分同步」只补缺失区间，无需全量；只有首次、换主、或 backlog 被覆盖才 FULLRESYNC。正确写法：答「部分同步可行性取决于 offset 是否仍在 backlog 窗口」，并强调 backlog 是固定大小环…"},{"h":"把哨兵的 quorum 当成 Raft 的多数派","d":"quorum 只是「确认主节点 SDOWN 的哨兵数门槛」，用来达成 ODOWN，通常小于哨兵总数；真正执行故障转移的 leader 选举才需要「多数派（>N/2）」票。正确写法：明确区分「ODOWN 的 quorum」与「leader 选举的多数派」，二者独立配置、语义不同。"},{"h":"选主规则记反优先级","d":"故障转移选新主顺序是 replica-priority 最小优先 → 复制 offset 最大（数据最新）优先 → runid 字典序最小优先。正确写法：priority 小优先（数值越小越想当主）、offset 大优先（数据越新越优先），别把方向记反。"},{"h":"MOVED 与 ASK 不分、以为都刷新路由表","d":"MOVED 表示槽归属已永久变更，客户端应刷新本地槽映射；ASK 仅发生在槽迁移中间态，是「本次临时」重定向，不刷新映射。正确写法：答「MOVED 刷新、ASK 不刷新」，并说明 ASK 只管该 key 本次去目标节点拿。"},{"h":"以为 Cluster 多 key 操作随便跨槽","d":"跨槽多 key（MSET/MGET/多 key Lua）默认报 CROSSSLOT 错误；必须用 hash tag {...} 把相关 key 约束到同一槽（如 order:{u1}:a、order:{u1}:b）。正确写法：答「默认跨槽不允许，用 hash tag 同槽」，并提醒 hash tag 设计不当会造成数据倾斜（大量 ke…"},{"h":"以为哨兵/Cluster 能彻底杜绝脑裂","d":"哨兵投票与 Cluster 故障转移都只是「逻辑共识」，极端网络分区下仍可能双主；min-replicas-to-write + min-replicas-max-lag 是「软隔离」（宁可停写也不分叉），不是硬 fencing。正确写法：说明脑裂的不可合并性根源，并指出 min-replicas 是 CP 取舍、会降低可用性，且从节…"},{"h":"以为 16384 槽可以随便改大提升粒度","d":"槽数固定 16384（14 位），槽分配表以 bitmap 经 gossip 传播，翻倍会使元数据与 CLUSTER SLOTS 体积翻倍；官方建议集群节点数 ≤1000，单槽过大在应用层再拆 key。正确写法：答「槽数固定 16384，是迁移粒度与元数据开销的折中」，不要说「可以调成更大」。"},{"h":"把主从复制当同步，主库宕机就当数据没丢","d":"Redis 复制是异步的：主库写完即返回，从库可能还差一段 offset。主库宕机时这部分写入直接消失，哨兵切换后「数据少了」但没有任何报错。 按 RPO 明确接受范围；需要背压就配 min-replicas-to-write 1 + min-replicas-max-lag 10，让主库在无健康副本时拒绝写。"}],"asks":[{"q":"Redis 主从复制中，全量同步和部分同步分别发生在什么场景？repl_backlog 起什么作用？","a":"全量同步（FULLRESYNC）：从节点首次同步、或断线过久/换主导致 offset 已滑出 repl_backlog 窗口时触发；主节点 fork + RDB 全量传给从节点，从节点清空载入后再补增量写命令。 部分同步（CONTINUE）：从节点短暂断线重连，只要断线期间写命令仍在主节点 repl_backlog 环形缓冲内（上报的 offset 仍在窗口），主节点只补发缺失区间，无需全量。 r…","fu":["从节点重启后为什么有时全量、有时部分同步？","repl_backlog 是固定大小，写入过快被覆盖会发生什么？"],"tag":"通用/字节"},{"q":"Redis 哨兵的 SDOWN 和 ODOWN 有什么区别？故障转移怎么选 leader、怎么选新主？","a":"SDOWN（主观下线）：单个哨兵在 down-after-milliseconds 内未收到主节点有效心跳，单方面判定主节点下线——是易错的本地观测。 ODOWN（客观下线）：达到 quorum 个哨兵都报告 SDOWN 后，哨兵集群共识判定主节点真正下线，才启动故障转移。注意 quorum 是「确认下线的哨兵数门槛」，不是 Raft 的多数派。 选 leader：ODOWN 后哨兵用类 Raft…","fu":["quorum 和 leader 选举的多数派为什么是两个不同概念？","选主规则里 priority 和 offset 的优先级方向分别是什么？"],"tag":"通用/腾讯"},{"q":"Redis Cluster 怎么分片？MOVED 和 ASK 重定向有什么区别？多 key 操作有什么限制？","a":"分片：把键空间分成 16384 个槽，slot = CRC16(key) & 16383，槽分配给各主节点（每主负责一段）；客户端按槽路由到对应节点。 MOVED vs ASK：MOVED 表示「槽归属已永久变更」，客户端应刷新本地槽→节点映射；ASK 仅发生在槽迁移中间态，是「本次临时」重定向，客户端不刷新映射，等迁移完成收到 MOVED 才更新。 多 key 限制：跨槽多 key（MSET/M…","fu":["为什么槽数固定是 16384 而不是更大？","迁移期间客户端怎么感知 ASK 并正确取数据？"],"tag":"通用/阿里"},{"q":"什么是 Redis 脑裂？怎么防护？这跟 CAP 有什么关系？","a":"脑裂：网络分区使原主与多数从节点/哨兵失联，但从节点侧选出新主继续服务；分区恢复后旧主「复活」，造成双主并存、两边各写各的、数据分叉且无法靠补增量自然合并（只能丢一方的写）。 防护：用 min-replicas-to-write + min-replicas-max-lag——当主节点发现「正常 ACK 且 lag ≤ 阈值的从节点数 < min-replicas-to-write」时，主动拒绝写…","fu":["min-replicas 为什么说是软隔离而不是硬 fencing？","Cluster 模式下脑裂概率为什么比主从+哨兵低？"],"tag":"通用/拼多多"}]},{"id":"mw-ch04","subj":"middleware","title":"缓存设计与三大经典问题","summary":"缓存穿透（布隆过滤器、空值缓存）、击穿（互斥重建、逻辑过期）、雪崩（TTL 打散、多级缓存、熔断降级）；缓存与数据库一致性（Cache Aside 先更新库再删缓存、延迟双删、binlog 订阅）；分布式锁的演进（SETNX → Redlo…","concepts":[{"id":"mw-ch04/01-cache-penetration","file":"01-cache-penetration.md","title":"一、缓存穿透：查不到的数据把压力打到数据库","kind":"flow","secs":[{"h":"① 布隆过滤器：用极少空间做「存在性」拦截","s":"（中立陈述）布隆过滤器是一个长度为 m 的 bit 数组，配 k 个独立哈希函数。写入元素时，对元素算 k 个哈希，把对应 k 个 bit 置 1；查询元素时同样算 k 个 bit，若全为 1 则「可能存在」，只要有一个为 0 则「一定…","c":null},{"h":"② 空值缓存：把「查无此物」也写进缓存","s":"（中立陈述）当查询的 key 在 DB 中确实不存在时，把「空结果（null / 特殊标记）」也按较短 TTL 写入缓存。这样同一 key 的重复穿透请求在 TTL 内直接命中空值缓存、不再查 DB。它常与布隆过滤器组合：布隆拦掉「结构…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"import zlib\n\nclass BloomFilter:\n    \"\"\"m 个 bit、k 个哈希的布隆过滤器。\"\"\"\n    def __init__(self, m_bits, k):\n        self.m = m_bits\n        self.k = k\n        self.bits = bytearray((m_bits + 7) // 8)\n\n…"}}]},{"id":"mw-ch04/02-breakdown-avalanche","file":"02-breakdown-avalanche.md","title":"二、缓存击穿与雪崩：热点失效与批量失效","kind":"timeline","secs":[{"h":"① 缓存击穿：一个热点 key 过期瞬间被海量并发打穿","s":"（中立陈述）某个被高并发访问的「热点 key」在过期瞬间，大量请求同时发现缓存失效，全部去查 DB 回源重建，造成 DB 瞬时压力陡增（甚至被打垮）。防护核心是「让并发回源只发生一次」或「不阻塞地异步重建」。见 examples/ex0…","c":null},{"h":"② 缓存雪崩：大量 key 在同一时刻集体失效","s":"（中立陈述）当大量缓存 key 使用相同或相近的 TTL，在某一时刻同时过期（或缓存服务整体宕机），瞬间所有请求 miss 并打到 DB，DB 瞬时过载甚至雪崩式崩溃。防护 = 把失效时刻打散 + 兜底。见 examples/ex06_…","c":null}]},{"id":"mw-ch04/03-consistency-update","file":"03-consistency-update.md","title":"三、缓存与数据库一致性 & 更新策略","kind":"timeline","secs":[{"h":"① Cache-Aside 的两种写顺序与并发脏数据","s":"（中立陈述）Cache-Aside（旁路缓存）是最常用的模式：读时「缓存 miss 则查 DB 并回填」，写时「更新 DB + 使缓存失效（删缓存）」。写顺序有两种：A. 先删缓存、再更新库；B. 先更新库、再删缓存。二者在并发读写交错…","c":null},{"h":"② 三大更新策略：Write-Through / Write-Behind / 延迟双删","s":"（中立陈述）缓存写策略决定「写请求如何落到缓存与 DB」：Write-Through（写穿） 同步双写缓存与 DB；Write-Behind（写回） 先写缓存、异步批量刷盘；延迟双删 是 Cache-Aside 的写增强（删→更新→延迟…","c":null}]},{"id":"mw-ch04/04-cache-design-practical-recipes","file":"04-cache-design-practical-recipes.md","title":"缓存设计实战手记：凯喵那个凌晨三点被打穿的首页","kind":"flow","secs":[{"h":"开场：缓存的本质是「用一致性换延迟」","s":"缓存之所以快，是因为它跳过了慢路径（数据库、下游服务），代价是数据可能不是最新的。所以缓存设计的所有争论，最终都归结为一个问题：这个业务能容忍多长时间的不一致。","c":{"lang":"python","code":"# 方案一：缓存空值（最简单，适合 id 有限的场景）\ndef get_user(uid):\n    key = f\"user:{uid}\"\n    val = redis.get(key)\n    if val is not None:\n        return None if val == \"__NULL__\" else json.loads(val)\n    row = db.query(\"SELECT * FROM user WHERE id=%s\", uid)\n    if row is None:\n        redis.setex(key, 300, \"__NULL__\")   # 短 TTL，防止长期占用\n…"}},{"h":"收尾：凯喵的缓存设计四问","s":"设计任何缓存前，先回答四个问题：","c":null}]}],"exams":[{"kind":"choice","q":"缓存穿透的成因与布隆过滤器的定位","stem":"关于缓存穿透与布隆过滤器，下列说法正确的是？ A. 布隆过滤器能确定某 key「一定存在」，可完全替代数据库查询 B. 布隆过滤器判定「不存在」时一定不存在（无假阴性）；判定「存在」时可能不存在（有假阳性） C. 布隆过滤器支持直接删除元素，删除后不影响其他元素的判定 D. 缓存穿透只能用布隆过滤器解决，缓存空值没有意义","opts":[{"k":"A","t":"布隆能确定一定存在"},{"k":"B","t":"无假阴性、有假阳性"},{"k":"C","t":"支持直接删除"},{"k":"D","t":"只能用布隆，空值无意义"}],"ans":"B","why":"布隆过滤器的 bit 由多个元素共享：某元素插入过的所有 bit 都为 1 才判「可能存在」，因此不存在假阴性（漏判），但存在假阳性（误判）。bit 共享也导致无法直接删除（清零会影响他元素），需 Counting Bloom Filter。缓存空值（短 TTL）是对穿透的有效兜底，二者常组合使用。"},{"kind":"choice","q":"缓存击穿与缓存雪崩的区别","stem":"关于击穿与雪崩，下列判断正确的是？ A. 击穿是「大量不同 key 同时失效」，雪崩是「单个热点 key 失效」 B. 击穿是「单个热点 key 失效后高并发全部回源」，雪崩是「大批 key 在同一时刻集体失效」 C. 雪崩只能通过加锁解决，与 TTL 设置无关 D. 逻辑过期（异步重建）只能用于雪崩，不能用于击穿","opts":[{"k":"A","t":"击穿是大量 key 同时失效"},{"k":"B","t":"击穿=单 key 热点；雪崩=大批 key 集体失效"},{"k":"C","t":"雪崩只能加锁，与 TTL 无关"},{"k":"D","t":"逻辑过期只能用于雪崩"}],"ans":"B","why":"击穿（breakdown / hot-key invalid）指单个被高频访问的热点 key 过期，瞬间大量请求同时回源；雪崩（avalanche）指大批 key 因统一 TTL 在同一时刻集体失效，DB 被整体打垮。雪崩的正解是 TTL 加随机抖动摊平失效 + 多级缓存 + 熔断降级，加锁并不对症；逻辑过期正是击穿的典型解法之一（不阻塞请求、异步重建）。"},{"kind":"coding","q":"实现布隆过滤器并计算误判率","stem":"用 Python 实现一个布隆过滤器：BloomFilter(m_bits, k)，提供 add(key) 与 contains(key)。 要求： 1. 用 zlib.crc32 派生 k 个哈希（禁止用内置 hash()，因其受 PYTHONHASHSEED 随机化影响，结果不可复现）； 2. 插入 n=1000 个元素后，用另外 1000 个从未插入的元素测误判率； 3. 打印理论误判率 (…","opts":[],"ans":"理论误判率与实测误判率数量级一致（相差不超过一个数量级）即可通过。","why":"误判率随 m 增大而降低、随 n 增大而升高；k 存在最优值 k_opt = (m/n)·ln2，k 过大反而升高误判（每个元素置更多 bit，碰撞更快）。哈希必须用确定性算法（crc32 / murmur），内置 hash() 在 PYTHONHASHSEED 随机化下每次进程结果不同，会导致输出不可复现。"},{"kind":"output","q":"Cache-Aside 两种写顺序的脏数据风险","stem":"一次写操作要「更新数据库 + 删除缓存」，一次并发读要「读缓存(miss) → 读库 → 回填缓存」。 请分别枚举「先删缓存后更新库」与「先更新库后删缓存」两种顺序下，写线程 2 个步骤与读线程 3 个步骤的所有合法交错（保持各线程内部顺序不变），并统计每种顺序下会产生「缓存与库不一致」的交错数量与占比。 问：哪种顺序的脏数据窗口更小？延迟双删为什么能进一步降低风险？","opts":[],"ans":"","why":"「先删缓存后更新库」的脏窗口大：删缓存后到更新库之间，读线程极易 miss 读到旧值并回填，随后写线程才更新库 → 缓存长期是旧值。「先更新库后删缓存」只有在「读线程恰好在写线程更新库之前读完旧值、且在删缓存之后才回填」这一极窄窗口才脏。延迟双删（更新库 → 删缓存 → 延迟 → 再删）用于清除那次迟到的旧值回填，延迟取「读库+回填」的经验上限。"},{"kind":"choice","q":"三种更新策略的一致性取舍","stem":"关于 Write-Through / Write-Behind / Cache-Aside，下列说法正确的是？ A. Write-Behind 是强一致策略，崩溃不丢数据 B. Write-Through 同步写缓存与库，一致性最好但写延迟高 C. Cache-Aside 由调用方维护缓存，写时通常「更新缓存」而非「删除缓存」 D. 三种策略对写延迟的影响相同","opts":[{"k":"A","t":"Write-Behind 强一致"},{"k":"B","t":"Write-Through 一致性最好但写延迟高"},{"k":"C","t":"Cache-Aside 写时更新缓存"},{"k":"D","t":"三者写延迟相同"}],"ans":"B","why":"Write-Through 同步双写缓存与库，一致性最强但每次写都要落库、延迟高；Write-Behind 先写缓存、异步批量刷盘，吞吐最高但崩溃会丢未刷盘的写，只适合可重建的计数类数据；Cache-Aside 由应用层维护，写时推荐「删除缓存」而非「更新缓存」——更新缓存在并发写下会产生乱序覆盖，且可能写进很少被读的冷数据。"},{"kind":"coding","q":"LRU 缓存（平台题，仅元数据）","stem":"设计和实现一个满足 LRU（最近最少使用）缓存约束的数据结构。请只阅读原题后在平台提交：本题只登记元数据与链接，不搬运题面。 能力点：哈希表 + 双向链表，O(1) 的 get/put；与本章「缓存淘汰策略」直接对应。","opts":[],"ans":"","why":"LRU 的工程落地要点：HashMap 定位 + 双向链表维护访问序，get 命中后移到头部，put 超容量淘汰尾部。Redis 的 maxmemory-policy=allkeys-lru 是近似 LRU（随机采样 N 个 key 淘汰最久未用的），用采样换取内存与 CPU，并非严格 LRU。"},{"kind":"coding","q":"设计 LFU 缓存（平台题，仅元数据）","stem":"为 LFU（最不经常使用）缓存设计并实现数据结构，get/put 均摊 O(1)。请只阅读原题后在平台提交：本题只登记元数据与链接，不搬运题面。 能力点：频次分桶 + 双向链表；与本章「LRU/LFU 近似淘汰」对应。","opts":[],"ans":"","why":"LFU 实现：HashMap<key, Node> + HashMap<freq, DoublyLinkedList> + minFreq 指针。Redis 的 LFU 用 24 位字段存「8 位对数访问计数 + 16 位衰减时间」，计数按概率增长并随时间衰减，因此能适应访问模式变化。"},{"kind":"explain","q":"穿透 / 击穿 / 雪崩：三者触发条件与防护手段的对应关系","stem":"请分别说明缓存穿透、缓存击穿、缓存雪崩的触发条件（数据在不在、key 有没有过期、是单个还是批量），并给出各自的主要防护手段。最后说明：为什么「缓存整体不可用」不属于这三者中的任何一个，却更需要单独设计兜底。","opts":[],"ans":"穿透：查询的数据本身不存在，缓存永远无法命中，请求每次都落到数据库。单个 key 也可能持续穿透。防护：缓存空值（短 TTL + 独立前缀）、布隆过滤器前置拦截、参数合法性校验 + 限流。 击穿：某个热点 key 恰好过期的瞬间，大量并发请求同时发现未命中并一起回源。特征是单 key、短时间、高并发。防护：互斥锁（只放…","why":"考点：三者的判据是「不存在 / 单点过期 / 批量过期」；基础设施层故障需要独立的降级路径。"}],"works":[{"h":"把布隆过滤器当成「精确判存在」结构","d":"布隆过滤器只能「确定某元素一定不存在」，不能「确定一定存在」：存在假阳性（误判）。正确写法：把它定位为穿透防护的「拦截器」而非数据源，对判定为「可能存在」的 key 仍要查缓存 / 查库；误判率公式 (1 e^{-kn/m})^k，降低误判靠增大 m（bit 数）或增多 k（哈希个数，但过多反而升高误判），不能指望它替代主键索引。"},{"h":"用布隆过滤器却忽略了「元素删除」难题","d":"标准布隆过滤器不支持删除（bit 是共享的，清零一个 bit 可能影响多个元素）；误删会把别的元素也判成「不存在」。正确写法：需要删除时用 Counting Bloom Filter（bit 换成计数器）；或业务上缓存是「只增不删 key 集合」时再上普通布隆，删除走重建过滤器。"},{"h":"缓存击穿用「查库前加锁」却没做单飞，并发仍全部回源","d":"只在方法上加 synchronized 而不区分「缓存是否已在重建中」，会导致后续请求排队挨个回源，回源次数 ≈ 并发数。正确写法：用单飞（singleflight）或「带令牌的互斥锁」——同一 key 同一时刻只允许一个线程回源，其余等待并复用结果（实测 200 并发回源 1 次）。"},{"h":"逻辑过期（异步重建）忘了兜底，热点 key 重建失败导致长期无值","d":"逻辑过期把 TTL 放内存、异步线程重建，若重建抛异常且不回写，该 key 会一直「逻辑已过期」返回空。正确写法：重建失败要重试 / 保留旧值 / 降级到同步回源，并监控重建成功率。"},{"h":"缓存雪崩用「统一 TTL」还以为加了过期就安全","d":"所有 key 同一时刻写入、同一 TTL，到期时集体失效，DB 瞬时被打满（实测 1000 个 key 同一时刻 100% 失效）。正确写法：TTL 加随机抖动（如 base + rand(0, spread)）把失效摊平；再配合多级缓存 + 熔断降级兜底。"},{"h":"以为「先删缓存、再更新数据库」是安全顺序","d":"并发下：写线程删缓存 → 读线程未命中读库（旧值）回填缓存 → 写线程才更新库，最终缓存是旧值、库是新值，脏数据持久。正确写法：优先「先更新数据库、再删缓存」（Cache-Aside 推荐序），并对读多写少场景辅以「延迟双删」清除读线程回填的旧值。"},{"h":"延迟双删的「延迟」时长拍脑袋","d":"删 → 更新库 → 睡眠 → 再删，若延迟小于「读线程回填缓存」的耗时，第二次删除删不掉脏值；若延迟过长又放大了窗口。正确写法：延迟取「读线程读库 + 回填缓存」的经验上限（通常几百 ms ~ 1s），并配合「读库时若缓存不存在才回填」的兜底，使双删真正清掉脏值。"},{"h":"把 Write-Behind 当成强一致","d":"Write-Behind 先写缓存、异步批量刷盘，崩溃会丢未刷盘的写，且读从库可能读到旧值。正确写法：只在可丢失 / 可重建（如计数、热指标）场景用，并做刷盘队列持久化与幂等；强一致需求用 Write-Through 或 Cache-Aside + 删缓存。"}],"asks":[{"q":"什么是缓存穿透、击穿、雪崩？分别怎么解决？","a":"穿透（penetration）：查询根本不存在的数据，缓存永远不命中，请求全部落到 DB。 - 解法：① 布隆过滤器拦截（无假阴性，判定不存在直接返回）；② 缓存空值并设短 TTL（如 60s）；③ 接口层做参数校验与 id 范围限制。 击穿（breakdown）：单个热点 key 过期瞬间，海量并发同时回源这一个 key。 - 解法：① 互斥锁 / 单飞（singleflight）——同一 ke…","fu":["布隆过滤器为什么不能删除元素？需要删除怎么办？","逻辑过期与互斥锁方案各自的缺点是什么？"],"tag":"字节跳动/阿里"},{"q":"如何保证缓存与数据库的一致性？「先删缓存还是先更新数据库」？","a":"推荐 Cache-Aside + 先更新数据库、再删缓存。 为什么不选「先删缓存后更新库」：删缓存后到更新库之间存在较长窗口，读线程极易 miss → 读到旧值 → 回填缓存，随后写线程才更新库，结果是「缓存=旧值、库=新值」，且这个脏值会一直存在到下次 TTL 或下次写，脏窗口很大。 「先更新库后删缓存」为什么更好：脏数据只可能发生在极窄窗口——读线程在写线程更新库之前读完旧值、且在删缓存之后才…","fu":["延迟双删的延迟时间怎么定？定长了有什么副作用？","删缓存失败怎么办？如何保证最终一致？"],"tag":"阿里/蚂蚁"},{"q":"布隆过滤器的误判率怎么算？如何降低？能删除吗？","a":"误判率公式：m 个 bit、k 个哈希函数、已插入 n 个元素时， P ≈ (1 - e^{-kn/m})^k 推导：单个 bit 在 n·k 次置位后仍为 0 的概率约 e^{-kn/m}；k 个 bit 全为 1（误判）即 (1 - e^{-kn/m})^k。 最优哈希个数：k_opt = (m/n)·ln2，此时误判率最低；k 过大反而升高（每元素置更多 bit，碰撞更快）。 如何降低：①…","fu":["m/n = 10 时理论误判率大约是多少？k 取几？","Counting Bloom Filter 的计数器溢出怎么办？"],"tag":"字节跳动/腾讯"},{"q":"Write-Through、Write-Behind、Cache-Aside 有什么区别？分别适用什么场景？","a":"| 策略 | 写路径 | 一致性 | 写延迟 | 适用场景 | |---|---|---|---|---| | Write-Through | 同步写缓存 + 写库 | 强一致 | 高（每次落库） | 对一致性要求高、写量不大的配置类数据 | | Write-Behind | 只写缓存，异步批量刷盘 | 最终一致，崩溃会丢 | 最低（写合并） | 可丢失/可重建的计数、点赞、热指标 | | Cac…","fu":["Write-Behind 崩溃丢数据怎么补偿？","Cache-Ase 首次读一定 miss，如何预热？"],"tag":"阿里/字节跳动"}]},{"id":"mw-ch05","subj":"middleware","title":"Kafka 架构：Topic、Partition 与 Replica","summary":"把消息队列抽象成分布式提交日志；分区数与并行度的关系；副本与 ISR 集合、Leader 选举与 HW/LEO；顺序性只在分区内成立；日志段、稀疏索引与零拷贝读取；与 RabbitMQ 等传统 MQ 的模型差异。","concepts":[{"id":"mw-ch05/01-commit-log-and-partition","file":"01-commit-log-and-partition.md","title":"一、提交日志模型：Kafka 为什么不是「队列」","kind":"flow","secs":[{"h":"① 从「队列」到「分布式提交日志」","s":"传统消息队列（RabbitMQ、ActiveMQ）的心智模型是队列：消息入队，被消费者取走后就删除；broker 维护每条消息的状态（已投递/已确认/待重投）。这套模型天然带来两个后果：","c":null},{"h":"② Topic / Partition / Offset：逻辑与物理的分离","s":"关键推论：","c":null},{"h":"③ 分区数与并行度：一个被低估的容量题","s":"分区数同时决定四件事：","c":{"lang":"text","code":"分区数 ≈ max( 目标吞吐 / 单分区目标吞吐,  预期最大消费者数,  broker 数 )"}}]},{"id":"mw-ch05/02-replica-isr-and-leader-election","file":"02-replica-isr-and-leader-election.md","title":"二、副本、ISR 与「不丢」的精确条件","kind":"flow","secs":[{"h":"① 副本因子与 Leader / Follower","s":"一个分区可以有 replication.factor 个副本，其中：","c":null},{"h":"② ISR 与 acks：把「不丢」写成可验证的条件","s":"acks 是生产端的参数，决定「什么时候算写入成功」：","c":{"lang":"text","code":"acks = all\nmin.insync.replicas = 2      # ISR 至少 2 个才允许写\nreplication.factor = 3       # 保证有 3 份物理拷贝"}},{"h":"③ LEO / HW / LSO：三个 offset 撑起一致性","s":"它们的推进关系：","c":{"lang":"text","code":"HW = min(LEO of all replicas in ISR)\n消费者可见范围 = [0, HW)          （普通场景）\n消费者可见范围 = [0, LSO)          （read_committed 事务场景，LSO <= HW）"}}]},{"id":"mw-ch05/03-storage-log-segment-and-zerocopy","file":"03-storage-log-segment-and-zerocopy.md","title":"三、存储、日志段与零拷贝：吞吐从哪来","kind":"stack","secs":[{"h":"① 日志段（segment）与稀疏索引","s":"一个分区的日志并不是单个无限增长的文件，而是被切成多个 segment，每个 segment 对应三个文件：","c":null},{"h":"② 零拷贝与页缓存：为什么 Kafka 能跑到百万级","s":"传统的「从磁盘读文件再发给网络」的路径是：","c":{"lang":"text","code":"1. 磁盘 -> 内核页缓存         (DMA 拷贝)\n2. 页缓存 -> 用户缓冲区        (CPU 拷贝)\n3. 用户缓冲区 -> Socket 缓冲区 (CPU 拷贝)\n4. Socket 缓冲区 -> 网卡       (DMA 拷贝)"}},{"h":"③ 日志保留与压实：数据不是「永久」的","s":"Kafka 清理日志有两种策略，由 cleanup.policy 决定：","c":{"lang":"properties","code":"log.retention.hours=72\nlog.retention.bytes=1073741824      # 与时间阈值取「先到者」\nlog.segment.bytes=1073741824        # 段大小决定删除的最小粒度\nlog.cleanup.policy=delete           # 或 compact：按 key 只保留最后一条"}}]},{"id":"mw-ch05/04-consumer-group-and-offset","file":"04-consumer-group-and-offset.md","title":"四、消费者组与位点：有序、不重、可重放","kind":"flow","secs":[{"h":"① 消费者组与 rebalance","s":"1. 成员变化：消费者加入、退出、崩溃（心跳超时）；","c":null},{"h":"② 分区分配策略：Range / RoundRobin / Sticky","s":"partition.assignment.strategy 可选：","c":{"lang":"text","code":"minimize( 负载不均衡 + λ · 迁移量 )"}},{"h":"③ 位点提交与三种投递语义","s":"提交时机决定投递语义：","c":{"lang":"properties","code":"enable.auto.commit=false"}}]}],"exams":[{"kind":"choice","q":"Kafka 的「消息消费」与传统队列的本质差异","stem":"关于 Kafka 的消息删除与消费进度，下列说法正确的是？ A. 消费者 ack 一条消息后，Kafka 立刻删除它 B. 消息的删除只由 retention（时间/大小）或 compaction 决定，与消费进度无关 C. 一个分区同时只能有一个消费者组消费 D. 消费者读取位置由 broker 统一维护，客户端无法指定","opts":[{"k":"A","t":"ack 即删除"},{"k":"B","t":"只由 retention/compaction 决定"},{"k":"C","t":"分区同时只能一个组消费"},{"k":"D","t":"位置由 broker 维护"}],"ans":"B","why":"Kafka 是「提交日志（commit log）」而非「队列」：消息写入后按 append-only 顺序持久化，只有当 retention.ms / retention.bytes 到期或触发 log compaction 时才被清理，与消费者是否读过无关。这正是「可重放」的根基——重置 offset 就能重读历史。C 错在多个消费者组各自维护独立进度、互不干扰；D 错在 o…"},{"kind":"choice","q":"acks 取值与耐久性边界","stem":"某 topic 配置 min.insync.replicas=2、副本因子 3。关于 acks 的耐久性，下列说法正确的是？ A. acks=1 表示 leader 与所有 follower 都落盘后才应答 B. acks=all 等价于 acks=-1，表示 ISR 中所有副本都写入后才应答 C. acks=0 表示 leader 落盘后即应答，不等待 follower D. acks=all…","opts":[{"k":"A","t":"acks=1 等所有 follower"},{"k":"B","t":"acks=all == acks=-1，等 ISR 全部"},{"k":"C","t":"acks=0 是 leader 落盘即应答"},{"k":"D","t":"acks=all 绝不丢"}],"ans":"B","why":"acks=0 是「发出即认为成功」，连 leader 是否收到都不保证；acks=1 只等 leader 本地落盘；acks=all（等价 acks=-1）等 ISR 中全部副本写入。注意 acks=all 的保证以「ISR 至少还有 min.insync.replicas 个副本」为前提：若 ISR 收缩到 1 个副本（其余被踢出同步），acks=all 会退化为 acks=…"},{"kind":"output","q":"HW 与消费者可见范围","stem":"某分区副本 LEO 分别为：leader=12、follower-A=12、follower-B=9，ISR = {leader, follower-A}（follower-B 已被踢出）。问：当前该分区的 HW 是多少？消费者最多能读到哪个 offset？ 请写出两个数字与依据。","opts":[],"ans":"HW = 12；消费者可读 offset 0..11（即 < HW）。","why":"HW（High Watermark）= ISR 中所有副本都已复制到的最大 offset，即 min(ISR 各副本 LEO) = min(12, 12) = 12。被踢出 ISR 的 follower-B（LEO=9）不参与 HW 计算——这正是 ISR 存在的意义：只让「同步中的副本」决定可见性，避免消费者读到随时可能因 leader 切换而被截断的数据。消费者只能读 [L…"},{"kind":"choice","q":"分区数与顺序性、并行度的三方取舍","stem":"一个 topic 有 3 个分区，消费者组起了 6 个消费者实例。下列说法正确的是？ A. 6 个实例都能分到分区，吞吐提升 2 倍 B. 只有 3 个实例能分到分区，其余 3 个空闲；单分区内消息有序、跨分区不保证 C. 增加消费者实例数一定能提升吞吐 D. 分区数可以随意减少以提升单分区吞吐","opts":[{"k":"A","t":"6 个都分到分区"},{"k":"B","t":"3 个干活 3 个空闲，分区内有序"},{"k":"C","t":"加消费者必然提吞吐"},{"k":"D","t":"分区可随意减少"}],"ans":"B","why":"一个分区在同一时刻只能被同组内的一个消费者消费，所以并行度上限 = min(分区数, 消费者数) = min(3, 6) = 3，多出的 3 个实例处于空闲（仅作为故障时的备位）。Kafka 只保证单分区内的顺序，跨分区无序；要保序必须让相关消息带同一个 key 落到同一分区。分区数只能增加不能减少（减少会破坏 key→分区 的稳定映射与已有数据归属），且增加分区同样会改变映射…"},{"kind":"fix_error","q":"修复「重复消费」的提交时机错误","stem":"以下伪代码在「处理后手动提交」的语义下做到了 at-least-once，但它有一个更严重的问题——写出问题所在并给出正确顺序。 python for msg in consumer: consumer.commit() # ① 先提交 handle(msg) # ② 再处理","opts":[],"ans":"for msg in consumer: handle(msg) # ① 先处理 consumer.commit() # ② 再提交（成功后才推进 offset）","why":"先提交再处理属于 at-most-once（最多一次）：一旦 ② 之前或 ② 中途崩溃，offset 已经推进，消息永不重投——丢消息。正确顺序是先处理、成功后提交，得到 at-least-once（可能重复）。若要求 exactly-once，需配合幂等生产者（PID + sequence）或把 offset 与业务结果放在同一个事务里提交（Kafka 事务 / sendOf…"},{"kind":"choice","q":"零拷贝的成立前提","stem":"关于 Kafka 的零拷贝（sendfile / FileChannel.transferTo），下列说法正确的是？ A. 零拷贝意味着数据完全不经内核，用户态直接收包 B. 传统 read+write 经过 4 次上下文切换与 4 次拷贝，零拷贝减少为 2 次上下文切换、3 次拷贝（无 CPU 参与的 DMA 拷贝 2 次） C. 开启 SSL/TLS 加密后零拷贝依然完全生效 D. 零拷贝要求…","opts":[{"k":"A","t":"数据完全不经内核"},{"k":"B","t":"2 次切换、3 次拷贝"},{"k":"C","t":"SSL 下完全生效"},{"k":"D","t":"必须先反序列化"}],"ans":"B","why":"传统路径：read 把数据从磁盘 DMA 到内核页缓存、再从内核拷贝到用户缓冲（4 次切换 / 4 次拷贝）；sendfile 让数据「磁盘→页缓存→socket 缓冲→网卡」，内核页缓存到 socket 缓冲仍有 1 次 CPU 拷贝，共 2 次上下文切换、3 次拷贝（其中 2 次为 DMA）。前提是数据不需要在用户态加工——所以一旦开启 SSL/TLS（需在用户态加密）或做…"},{"kind":"coding","q":"设计循环队列（对应 Kafka 日志段的环形缓冲思想）","stem":"Kafka 的日志写入与页缓存管理大量依赖「定长环形缓冲」的思想：容量固定、读写指针循环推进、通过 (head + n) mod capacity 定位。LeetCode 622「设计循环队列」正是这一数据结构的经典实现题。 本题仅提供平台链接与元数据，不在本 App 内搬运题面正文。 请前往平台作答。","opts":[],"ans":"","why":"考点：用固定数组 + head/count（或 head/tail 加一个空位哨兵）实现 O(1) 的 enQueue / deQueue / Front / Rear / isEmpty / isFull。与 Kafka 的关联点：segment 文件写入位置、log.index 的稀疏索引槽位计算，本质都是「容量固定的环形/线性缓冲 + 取模定位」；理解哨兵空位法能顺带解释…"},{"kind":"coding","q":"自命题：用 murmur2 实现分区器并评估分布均匀度","stem":"实现 Kafka 默认分区器的核心逻辑，并对一组 key 评估分区分布的均匀度。 要求： 1. 实现 murmur2(data: bytes) -> int（32 位，与 Kafka Utils.murmur2 一致的算法，返回值按无符号 32 位处理）。 2. 实现 partition_of(key, num_partitions) = to_positive(murmur2(key)) % n…","opts":[],"ans":"","why":"关键点：① murmur2 必须按 32 位无符号做乘加，中间结果要 & 0xffffffff 截断，否则 Python 大整数会算错；② 末尾的 h ^= h >> 13; h = m; h ^= h >> 15 是 avalanche 混合，不能省；③ Kafka 用 & 0x7fffffff 而非 abs()，因为 abs(-2^31) 在 Java int 上仍是负数…"}],"works":[{"h":"把 Kafka 当传统队列，以为「消费即删除」","d":"Kafka 的消息与消费进度无关，只按 retention.ms/retention.bytes 或 compact 清理。所以同一个 topic 可以被多个消费者组各自完整消费（这就是可重放能力）。正确认识：Kafka 是「可重放的分布式日志」，不是「取出即销毁的队列」。"},{"h":"以为分区数可以随便增减","d":"分区只能增加，不能减少（减少会导致数据丢失与位点错乱，Kafka 不直接支持）。更关键的是：增加分区会改变 hash(key) % N 的落点，破坏跨分区的顺序连续性。正确做法：上线前按 max(目标吞吐/单分区吞吐, 消费者数, broker 数) 规划到位并留余量。"},{"h":"认为「分区越多吞吐越高」","d":"分区数增加会带来：每分区独立的 .log/.index/.timeindex 文件句柄、ISR 维护心跳、rebalance 与故障恢复时间上升。正确认识：存在边际收益递减的最优点；分区数超过消费者数就是纯浪费（多余消费者空闲）。"},{"h":"只配 acks=all 就以为不丢消息","d":"若 ISR 收缩到只剩 Leader，acks=all 等价于 acks=1。必须同时配 min.insync.replicas=2（ISR 不足时拒绝写入）+ replication.factor=3，才是真正的不丢条件。"},{"h":"把「有序」理解成全局有序","d":"Kafka 只保证单分区内有序。全局有序只能用一个分区（牺牲全部并行度）。正确表述：先明确「顺序的边界是分区」，再用分区键把需要保序的实体（如同一订单 id）路由到同一分区，并注意 max.in.flight.requests.per.connection > 1 时需开启幂等才能避免重试乱序。"},{"h":"消费者数超过分区数，以为能提速","d":"组内同一分区只能被一个消费者消费，因此有效并行度 = min(消费者数, 分区数)。多出来的消费者完全空闲。正确做法：先把分区数提上去（或按分区数规划消费者实例数），再谈扩容。"},{"h":"用默认的自动提交位点，却期望「处理完才算消费成功」","d":"enable.auto.commit=true 提交的是 position（poll 到的位置）而非处理完成的位置，默认配置等价于 at-most-once，处理中崩溃即丢消息。正确做法：enable.auto.commit=false，处理完成后手动提交。"},{"h":"以为「先处理再提交」就不会重复","d":"先处理再提交是 at-least-once，rebalance 或提交失败都会导致重复消费。正确做法：消费端必须幂等（唯一键、去重表、upsert），或在上游保证「同 key 同分区」后用状态去重。"}],"asks":[{"q":"为什么说 Kafka 是「提交日志」而不是「消息队列」？这个设计带来什么好处？","a":"核心区别在于消息的生命周期由谁决定。 传统 MQ（RabbitMQ / ActiveMQ）以「队列」为抽象：消息被消费并 ack 后即从队列移除，是个会消费掉的通道。Kafka 以「提交日志（commit log）」为抽象：消息 append-only 追加到分区末尾，永不为消费而删除，只在 retention.ms / retention.bytes 到期或 cleanup.policy=com…","fu":["retention.bytes 和 retention.ms 同时配置时以哪个为准？（满足任一即删除）","log compaction 保留的是什么？（每个 key 的最新值，适合 changelog / 状态恢复场景）"],"tag":"字节跳动/美团"},{"q":"Kafka 如何保证消息不丢？请分别从生产者、broker、消费者三个环节说明。","a":"必须三端同时收紧，任一环有缺口都会丢。 ① 生产者：acks=all（等待 ISR 全部副本落盘）+ retries 足够大 + 开启幂等（enable.idempotence=true）防止重试导致重复。注意 acks=all 的效果取决于 min.insync.replicas：它规定「ISR 至少剩几个副本时才接受写入」，设为 2 且副本因子 3 时，若 ISR 只剩 1 个副本，写入会被拒…","fu":["acs=all 但 ISR 只剩 leader 一个副本时会怎样？（若 min.insync.replicas=2 则写…","为什么说 at-least-once 比 at-most-once 更常用？（丢数据通常比重复更不可接受）"],"tag":"腾讯/快手"},{"q":"ISR 是什么？为什么需要它，而不是让所有副本都必须同步？","a":"ISR（In-Sync Replicas）是「与 leader 保持同步的副本集合」，包含 leader 自己。判定标准是副本的 LEO 落后 leader 不超过 replica.lag.time.max.ms（默认 30s）——注意 Kafka 2.5+ 用「是否按时发起 fetch 请求」而非「消息条数差」来判定，避免流量低谷时的误踢。 为什么不能要求全部副本同步？ 这是可用性与一致性的经典…","fu":["controller 如何决定换 leader？（优先从 ISR 中选 LEO 最大的副本）","unclean.leader.election.enable=true 有什么代价？（可能选到落后副本 -> 丢数据 +…"],"tag":"字节跳动/京东"},{"q":"消费者组 rebalance 触发条件有哪些？如何避免 rebalance 引发的重复消费与消费停顿？","a":"触发条件（三类）： 1. 组内成员数量变化——新消费者加入、消费者主动离开、消费者崩溃（会话超时 session.timeout.ms）。 2. 订阅的 topic 分区数变化（管理员扩容分区）。 3. 订阅的 topic 集合变化（正则订阅时新 topic 被创建）。 rebalance 的代价： - Stop-The-World：Eager 协议下所有消费者先放弃全部分区（revoke），再重…","fu":["max.poll.interval.ms 设小了会怎样？（处理超时被踢 -> rebalance 风暴）","range 与 round-robin 分配策略的差别？（range 按 topic 逐段切分，分区多时容易不均）"],"tag":"阿里巴巴/美团"}]},{"id":"mw-ch06","subj":"middleware","title":"Kafka 生产者与消费者机制","summary":"生产者分区策略与 acks=0/1/all 的可靠性权衡；幂等生产者（PID + 序列号）与生产者事务；消费者组的 rebalance 协议与触发条件；位移提交（自动 vs 手动、同步 vs 异步）与重复消费；__consumer_offs…","concepts":[{"id":"mw-ch06/01-producer-partitioning-and-batching","file":"01-producer-partitioning-and-batching.md","title":"一、生产者：分区策略、攒批与发送链路","kind":"flow","secs":[{"h":"① 分区器：消息如何落到某个 partition","s":"Kafka 的并行单位是 分区，不是 Topic。所以「消息去哪」这个问题，等价于「并行度怎么分配」。","c":null},{"h":"② 攒批与吞吐：batch.size / linger.ms / compression","s":"Kafka 的高吞吐不是来自「每条消息发得快」，而是来自把很多条消息合并成一次请求。","c":{"lang":"java","code":"Properties p = new Properties();\np.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, \"localhost:9092\");\np.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);\np.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class);\n\n// 攒批三件套\np.put(ProducerConfig.BATCH_SIZE_CONFIG, 32 * 1024);   // 单批上限 32KB\np.put(ProducerConfig.LINGER_MS_CONFIG, 5);            // 最多等 5ms 凑批\np.put(ProducerConfig.COMPRESSION_TYPE_CONFIG, \"lz4\"); // 压缩在批级别生\n…"}},{"h":"③ 发送链路：从 send() 到 Broker","s":"两个要点：","c":{"lang":"text","code":"send(record)\n  → Interceptor 链（onSend）\n  → Serializer（key / value 序列化）\n  → Partitioner（决定 partition）\n  → RecordAccumulator（按 partition 分桶，攒成 batch）\n  → Sender 线程（每 broker 一个 in-flight 请求）\n  → NetworkClient（NIO）\n  → Broker\n  → 回调（Callback / Future）在 Sender 线程完成"}},{"h":"小结","s":"","c":null}]},{"id":"mw-ch06/02-acks-retries-and-idempotence","file":"02-acks-retries-and-idempotence.md","title":"二、可靠性开关：acks、重试、幂等与事务","kind":"timeline","secs":[{"h":"① acks：三档语义与各自的丢失窗口","s":"⚠️ 关键误解：acks=all 不等于「写入所有副本」。它等于「写入当前 ISR 中的全部副本」。","c":null},{"h":"② min.insync.replicas：与 acks=all 的配合","s":"acks=all 决定「等谁确认」，min.insync.replicas 决定「ISR 至少要几个才允许写入」。两者是正交的。","c":null},{"h":"③ 幂等生产者与事务","s":"实现「流处理场景的 exactly-once」。代价是：需要 transactional.id、事务超时管理、以及只能保证 Kafka 内部的原子性","c":{"lang":"java","code":"Properties p = new Properties();\np.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, \"localhost:9092\");\np.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);\np.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class);\np.put(ProducerConfig.TRANSACTIONAL_ID_CONFIG, \"order-tx-1\");  // 跨重启稳定，才能接续去重状态\np.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, true);        // 事务的前置条件，开了才合法\n\nKafkaProducer<String, String> producer = new Kafk\n…"}},{"h":"小结","s":"","c":null}]},{"id":"mw-ch06/03-consumer-group-and-rebalance","file":"03-consumer-group-and-rebalance.md","title":"三、消费者组：分区归属与 rebalance","kind":"flow","secs":[{"h":"① 组模型：分区与消费者的对应关系","s":"剩下的消费者没有分区可分。它们仍然在组里（会参与心跳），但 poll() 永远拿不到数据。","c":null},{"h":"② 分区分配策略","s":"它的收益在大集群（几十个消费者）上尤其明显：Eager 协议下每次 rebalance 都会导致所有消费者同时放弃所有分区，","c":null},{"h":"③ rebalance：触发条件与协议演进","s":"1. 成员数变化：新消费者加入、消费者主动退出（close()）、消费者崩溃；","c":null},{"h":"小结","s":"","c":null}]},{"id":"mw-ch06/04-offset-commit-and-delivery-semantics","file":"04-offset-commit-and-delivery-semantics.md","title":"四、位移提交：重复与丢失的正确边界","kind":"flow","secs":[{"h":"① 位移提交的四种方式","s":"⚠️ 自动提交的致命之处：它在 poll() 时自动提交上一批的位移。也就是说，","c":{"lang":"java","code":"props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, \"false\");\nwhile (running) {\n    ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(200));\n    for (ConsumerRecord<String, String> r : records) {\n        process(r);           // 业务处理\n    }\n    consumer.commitSync();    // 处理成功后才提交 -> 至少一次\n}"}},{"h":"② 三种交付语义与它们的代价","s":"在 Kafka 内部原子提交。所以它在流处理管道（Kafka → Flink/Streams → Kafka）中成立，","c":null},{"h":"③ __consumer_offsets：位移存在哪","s":"Kafka 的位移不是存在 ZK 里（0.9 之后已迁移），而是存在一个内部 Topic：__consumer_offsets。","c":{"lang":"text","code":"kafka-consumer-groups.sh --bootstrap-server <broker> --describe --group <group>"}},{"h":"小结","s":"","c":null}]},{"id":"mw-ch06/05-reliability-recipe","file":"05-reliability-recipe.md","title":"生产端可靠性实战：不丢、不重、有序","kind":"flow","secs":[{"h":"一、生产者配置：不丢的第一道闸","s":"","c":{"lang":"yaml","code":"# producer.properties —— 三件套缺一不可\nbootstrap.servers=broker1:9092,broker2:9092,broker3:9092\nacks=all                    # 等所有 ISR 副本写成功\nenable.idempotence=true      # 开启幂等：重试不会产生重复记录\nmax.in.flight.requests.per.connection=5   # 幂等下最多允许 5 个在途请求\nretries=2147483647          # 无限重试（由 delivery.timeout 控制总时长）\ndelivery.timeout.ms=120000  # 单次投递总超时\ncompression.type=zstd       # 批量压缩，磁盘与网络都省\nlinger.ms=10                 # 攒 10ms 换吞吐（延迟敏感场景调 0）\n…"}},{"h":"二、幂等生产者：重试为什么不产生重复","s":"","c":{"lang":"java","code":"// 幂等由 broker 侧维护的 producerId + epoch 实现：同一事务内重试会被去重\nProperties props = new Properties();\nprops.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, \"broker1:9092\");\nprops.put(ProducerConfig.ACKS_CONFIG, \"all\");\nprops.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, \"true\");\nprops.put(ProducerConfig.MAX_IN_FLIGHT_REQUESTS_PER_CONNECTION, \"5\");\nprops.put(ProducerConfig.RETRIES_CONFIG, Integer.MAX_VALUE);\nprops.put(ProducerConfig.DELIVERY_TIMEOUT_MS_CONFIG, \"120000\");\n\n…"}},{"h":"三、消费端幂等：至少一次 + 去重表","s":"关键顺序：先处理并落库，最后提交位移。反过来（先提交后处理）会丢消息，","c":{"lang":"python","code":"# 至少一次语义下，同一条消息会被投递多次；用业务唯一键 + 唯一索引去重\nimport sqlite3, json\n\nconn = sqlite3.connect(\"app.db\")\nconn.execute(\"CREATE TABLE IF NOT EXISTS processed_orders (order_id TEXT PRIMARY KEY, done_at INTEGER)\")\nconn.commit()\n\ndef handle(msg):\n    order = json.loads(msg.value)\n…"}},{"h":"四、rebalance：消费被打断时在发生什么","s":"","c":{"lang":"text","code":"触发 rebalance 的四种情况：\n1) 消费者加入/退出（扩缩容、滚动重启）\n2) 分区数变化（给 topic 加分区）\n3) 消费超时（max.poll.interval.ms 到了还没 poll）\n4) 心跳丢失（session.timeout.ms 内没心跳）\n\nEager（默认 RangeAssignor）：\n   撤销所有分区 → 重新分配 → 全部消费者重新加入\n   → 期间该组所有分区都暂停消费\n…"}},{"h":"五、上线前自检清单","s":"","c":{"lang":"text","code":"□ acks=all + min.insync.replicas=2 + replication.factor=3 都配了吗\n□ unclean.leader.election 关闭了吗\n□ 生产者 enable.idempotence=true 了吗（否则重试会写重复）\n□ 消费端手动提交位移，且先处理后提交吗\n□ 业务有唯一键 + 去重表吗（否则重复消费必然出事）\n□ key 设计能保证需要的顺序粒度吗（同 key 才同分区）\n□ max.poll.interval.ms 大于单批耗时 P99 吗\n□ 监控：lag、producer error rate、rebalance 频次、DLQ 速率"}},{"h":"🧑‍💻 程序员视角","s":"生产者「不丢」要同时满足三个条件：acks=all（所有 ISR 确认）、retries 足够大、enable.idempotence=true（幂等生产者防重试重复）。只设 acks=all 而不开幂等，重试仍会产生重复消息——这是「…","c":null},{"h":"🎓 博士生视角","s":"消息系统的可靠性分三个层面：生产端（不丢）、存储端（副本 + ISR）、消费端（幂等）。Kafka 的 acks 与 min.insync.replicas 共同决定「写成功」的含义，acks=all + min.insync.repl…","c":null},{"h":"📚 考研者视角","s":"后端面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"acks=all 究竟等价于写入几个副本","stem":"关于 acks=all（即 -1）的语义，下列说法正确的是？ A. 它保证消息一定写入全部 replication.factor 个副本 B. 它要求写入当前 ISR 中的全部副本，因此 ISR 收缩后保护力度会下降 C. 它等价于等待所有 broker（含非副本）确认 D. 它比 acks=1 慢，但两者在数据安全性上等价","opts":[{"k":"A","t":"保证写入全部 RF 个副本"},{"k":"B","t":"写入当前 ISR 全部，ISR 收缩则保护下降"},{"k":"C","t":"等所有 broker 确认"},{"k":"D","t":"与 acks=1 安全性等价"}],"ans":"B","why":"acks=all 的准确含义是「等待当前 ISR 中所有副本完成写入」，而不是「所有的 replication.factor 个副本」。ISR 会因副本落后而收缩：若只剩 leader，acks=all 就退化成 acks=1。 所以只写 acks=all、不配 min.insync.replicas 是纸糊的持久性保证。 C 错（非副本不参与）；A 错（不是全部 RF）；D…"},{"kind":"choice","q":"min.insync.replicas 与 acks=all 的关系","stem":"replication.factor=3、acks=all 已配置。若 min.insync.replicas 仍为默认值 1， 当前 ISR 收缩到只有 leader 一个副本。此时最可能发生的是？ A. 生产者写入被拒绝，抛出 NotEnoughReplicasException B. 写入正常成功，但数据已失去持久性保护，leader 宕机即丢 C. Kafka 自动把 ISR 恢复到 3…","opts":[{"k":"A","t":"写入被拒绝"},{"k":"B","t":"写入成功但已无保护"},{"k":"C","t":"自动恢复 ISR"},{"k":"D","t":"自动降级并警告"}],"ans":"B","why":"min.insync.replicas 是写入准入条件：ISR 大小 < 它时拒写。 默认值为 1，所以在 ISR=1 时 1 >= 1 成立 → 照常写入，只是此时的 acks=all 等同于 acks=1。 这不是自动降级（Kafka 不打印这种警告，也不会自动改配置），而是配置组合本身的漏洞。 修正方式是把 min.insync.replicas 设为 2（3 副本场景）…"},{"kind":"output","q":"同一批消息在两种提交顺序下的重复/丢失量","stem":"一批 8 条消息，消费者在第 5 条处理完之后崩溃。 - 写法甲：每条处理成功后立即 commitSync() - 写法乙：进入循环时先 commitSync() 提交整批，再处理 请分别写出重启后重复的条数与丢失的条数（按至少一次 / 至多一次的语义推理）。","opts":[],"ans":"甲（先处理后提交，至少一次）: 重复 0 条, 丢失 0 条 乙（先提交后处理，至多一次）: 重复 0 条, 丢失 3 条","why":"写法甲是逐条提交：第 5 条处理完成后已提交位移，崩溃时前 5 条都已确认， 重启从第 6 条开始 → 既不重复也不丢失（在崩溃点恰好在提交之后的前提下）。 若崩溃发生在「处理完但提交前」，则重放 1 条 —— 这才是至少一次的典型代价。 写法乙把整批位移在处理之前提交：崩溃后位移已前进到第 8 条，重启从第 9 条开始， 第 6、7、8 条从未被处理却已跳过 → 丢失 3 条…"},{"kind":"choice","q":"消费者数超过分区数会发生什么","stem":"某 Topic 有 6 个分区，某个消费者组已有 8 个消费者实例。下列说法正确的是？ A. Kafka 会自动把一个分区同时分配给多个消费者以提升吞吐 B. 有 2 个消费者因为没有分区而空闲，但它们仍然是组的成员并正常发送心跳 C. 多出的 2 个消费者会被自动踢出组 D. 集群总消费吞吐会随消费者数线性增长到 8 倍","opts":[{"k":"A","t":"分区可被多消费者共享"},{"k":"B","t":"2 个空闲但仍是成员"},{"k":"C","t":"多出的被踢出组"},{"k":"D","t":"吞吐线性增长到 8 倍"}],"ans":"B","why":"Kafka 的核心不变式是「一个分区在同一时刻只能被组内一个消费者消费」， 因此并行度上限 = min(消费者数, 分区数) = 6。多出的 2 个消费者没有分区可分， 但它们仍是组成员（心跳正常、会参与 rebalance），只是 poll() 永远返回空。 A 违反不变式；C 错（空闲不等于死亡）；D 错（吞吐被分区数封顶）。"},{"kind":"fix_error","q":"修复「处理超时被踢出组」导致的反复 rebalance","stem":"下面这段消费者代码在生产环境频繁触发 rebalance，日志里能看到 Member ... has left the group 与 This member will leave the group because consumer poll timeout has expired。 java props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG,…","opts":[],"ans":"props.put(ConsumerConfig.MAX_POLL_RECORDS_CONFIG, \"200\"); // 200300ms = 60s < 300s props.put(ConsumerConfig.SESSION_TIMEOUT_MS_CONFIG, \"45000\"); // 默认值即可 props.…","why":"问题一：max.poll.records=2000 × 300ms = 600s，远超默认 max.poll.interval.ms=300s。 后台心跳正常发送也没用 —— 判定「消费者是否存活」包含「它是否还在正常 poll()」。 修正：把 max.poll.records 降到 200（200×300ms = 60s，留 5 倍余量），或调大 max.poll.inte…"},{"kind":"choice","q":"enable.idempotence 的能力边界","stem":"开启 enable.idempotence=true 后，关于它能与不能解决的问题，正确的是？ A. 能防止消费者重复消费；不能防止生产者重试重复 B. 能防止生产者重试导致的同分区重复；不能防止跨会话、跨分区的重复 C. 能保证跨分区的全局去重；但不能保证顺序 D. 能保证 exactly-once 语义；不能保证 acks 的耐久性","opts":[{"k":"A","t":"防消费重复，不防生产重试"},{"k":"B","t":"防同分区重试重复，不防跨会话/跨分区"},{"k":"C","t":"能全局去重，不保证顺序"},{"k":"D","t":"保证 exactly-once，不保证 acks"}],"ans":"B","why":"幂等生产者用 (PID, 分区, 序列号) 三元组在 broker 端去重，所以它的作用域是 单分区 + 单会话：分区不同则去重域不同；生产者重启后 PID 变化、去重状态不延续。 A 错（它是生产端机制，与消费者重复无关）；C 错（跨分区不生效）； D 错（幂等会自动把 acks 提升为 all，且 exactly-once 还需要事务，幂等本身不够）。 补充：开启幂等后 K…"},{"kind":"coding","q":"设计循环队列（对应 Kafka 日志段与攒批缓冲的环形结构）","stem":"Kafka 的日志段写入、RecordAccumulator 的分区缓冲都建立在「容量固定的循环缓冲」 之上：读写位置循环推进、用取模定位、用哨兵或计数器区分「空」与「满」。 LeetCode 622「设计循环队列」正是这一结构的经典实现题。 本题仅提供平台链接与元数据，不在本 App 内搬运题面正文。 请前往平台作答。","opts":[],"ans":"","why":"考点：用定长数组 + head/count（或 head/tail + 一个空位哨兵）实现 O(1) 的 enQueue / deQueue / Front / Rear / isEmpty / isFull。 与 Kafka 的关联：RecordAccumulator 按分区维护 batch 队列（有界缓冲，受 buffer.memory 约束）， 满了就阻塞 send()…"},{"kind":"coding","q":"自命题：实现 murmur2 分区器并评估分布均匀度","stem":"实现 Kafka 客户端使用的 murmur2 哈希（种子 0x9747b28c、乘子 0x5bd1e995、右移 24）， 并用它实现 partition(key, numPartitions) = (murmur2(key) & 0x7fffffff) % numPartitions。 要求： 1. 对 240 个形如 order-00000 的 key，在 12 个分区上统计分布，输出标准差…","opts":[],"ans":"见 examples/ex01-hash-partitioner-comparison.json","why":"关键点有三个： 1. 必须做 32 位截断（& 0xffffffff），否则 Python 的任意精度整数会让结果与 Java 实现不一致； 2. 最后要取正数（& 0x7fffffff），因为 murmur2 返回值可能为负，负数取模在 Java 与 Python 中行为不同 （Java % 保留符号，Python % 返回非负），Kafka 客户端统一用正数； 3. nai…"}],"works":[{"h":"acks 只在生产者设，忘了 min.insync.replicas","d":"只写 acks=all 而 min.insync.replicas 仍是默认 1 时，ISR 收缩到只剩 leader 后 acks=all 退化成 acks=1，照样丢数据。正确做法：生产端 acks=all 必须配 broker/Topic 端 min.insync.replicas ≥ 2（3 副本场景）。"},{"h":"enable.auto.commit=true 却不处理业务失败","d":"自动提交在 poll() 时提交上一批的位移，与业务处理结果无关。处理到一半崩溃 → 这批消息永久丢失且无任何日志。正确做法：生产环境设 enable.auto.commit=false，处理成功后手动提交。"},{"h":"commitSync() 写在业务处理之前","d":"这是主动选择 at-most-once。一旦处理抛异常，位移已经前进，消息再也回不来。正确顺序：先处理、成功后再提交（at-least-once），重复由业务幂等消化。"},{"h":"以为 enable.idempotence=true 能防止消费者重复","d":"幂等生产者是生产端的去重（PID + 分区 + 序列号），与消费者的重复消费毫无关系。防重复消费只能靠业务幂等。"},{"h":"以为 acks=all 就等于\"写入所有副本\"","d":"它等于「写入当前 ISR 中的全部副本」。ISR 会因副本落后而收缩，所以它不是「写入全部 replication.factor 个副本」。"},{"h":"消费者数超过分区数还继续加机器","d":"并行度上限是 min(消费者数, 分区数)，多出来的消费者永远空闲（仍在组内、仍发心跳，但拿不到分区）。提吞吐要么加分区（破坏 key 映射，需谨慎），要么优化单条处理耗时。"},{"h":"max.poll.interval.ms 当成网络超时","d":"它管的是两次 poll() 之间的业务处理时长（默认 5 分钟）。心跳由后台线程正常发送也救不了：一次 poll() 返回的批次处理超过 5 分钟，消费者照样被踢出组并触发 rebalance。"},{"h":"session.timeout.ms 调得过小","d":"网络抖动（GC 停顿、跨机房抖动）就会导致心跳超时 → 被踢 → rebalance → 重复消费 + 消费停摆。约束是 heartbeat.interval.ms < session.timeout.ms / 3。"}],"asks":[{"q":"Kafka 如何保证消息不丢？","a":"要分三个环节回答，每个环节给一条对策，而不是只背一句「acks=all」。 ① 生产端 - 配置 acks=all（等当前 ISR 全部确认）； - retries 调大（或 retries=Integer.MAX_VALUE）； - 开启 enable.idempotence=true（它会自动把 acks 提升为 all，并限制 max.in.flight ≤ 5）； - 必须处理回调异常 —…","fu":["为什么只配 acks=all 不够？请说出 min.insync.replicas 的作用。","acks=all 和 replication.factor=3 是不是同一件事？"],"tag":"字节跳动/美团"},{"q":"为什么会重复消费？怎么解决？","a":"先说结论：重复消费不是 bug，而是 at-least-once 语义的必然代价 —— 除非引入跨系统事务。 两个具体窗口： 1. 处理完但提交位移前崩溃 → 重启后从上次提交点重放； 2. rebalance 导致分区易主 → 新消费者从旧提交点开始重放。 为什么不能靠\"调参\"根治：因为「业务处理」与「位移提交」在两个独立系统上（业务可能在 MySQL， 位移在 __consumer_offse…","fu":["enable.idempotence=true 能防止消费者重复吗？","rebalance 为什么也是重复消费的高发窗口？"],"tag":"阿里巴巴/腾讯"},{"q":"rebalance 是什么？如何减少 rebalance？","a":"定义：消费者组内重新分配「分区 → 消费者」归属的过程。 三类触发条件： 1. 成员变化：新消费者加入、消费者主动 close()、消费者崩溃被踢； 2. 订阅变化：subscribe() 的 Topic 列表变更； 3. 分区数变化：Topic 增加了分区。 「假故障」才是线上主因（这三条最值得展开）： - max.poll.interval.ms 太小 → 业务处理超时被踢（注意它管的不是网络…","fu":["max.poll.interval.ms 与 session.timeout.ms 的区别是什么？","StickyAssignor 和 CooperativeStickyAssignor 有什么不同？"],"tag":"字节跳动/美团"},{"q":"Kafka 的三种消息交付语义分别怎么实现？","a":"一张表说清，顺序不能错： | 语义 | 实现方式 | 代价 | |---|---|---| | at-most-once | enable.auto.commit=true，或先 commitSync() 再处理 | 可能丢 | | at-least-once | enable.auto.commit=false + 处理成功后 commitSync() | 可能重（需业务幂等） | | exac…","fu":["exactly-once 为什么必须依赖事务？","at-least-once 的重复规模怎么估算？"],"tag":"腾讯/百度"}]},{"id":"mw-ch07","subj":"middleware","title":"消息可靠性：不丢、不重、有序","summary":"消息丢失的三个环节（生产端/存储端/消费端）与逐项对策；重复消费的本质（at-least-once）与业务幂等设计（唯一键、去重表、状态机）；顺序消息的实现约束与代价；事务消息与 exactly-once 的真实成本；死信队列与重试策略。","concepts":[{"id":"mw-ch07/01-loss-three-stages","file":"01-loss-three-stages.md","title":"一、消息丢失的三个环节：生产端、存储端、消费端","kind":"stack","secs":[{"h":"① 生产端：send() 返回成功之前的那段风险","s":"生产者调用 send() 之后，消息要先在客户端攒批，再经网络到达 leader。这一段的风险有两类：根本没发出去（攒批消息还在内存里，进程崩溃）和以为发出去了（acks=0 时不等任何确认）。","c":null},{"h":"② 存储端：副本、ISR 与「少数派当选」","s":"消息到了 broker 也不是终点。写入 leader 的页缓存（page cache）后，是否落盘取决于刷盘策略；副本是否同步取决于 ISR；而一旦发生 leader 选举，谁来当新 leader 决定了已确认的数据是否还在。","c":null},{"h":"③ 消费端：位移提交时机与「静默丢消息」","s":"消费端是最容易被忽视的丢失点，因为丢失往往发生在业务代码看起来完全正常的时候——enable.auto.commit=true 就是典型陷阱。","c":null},{"h":"小结","s":"<!-- injected-code -->","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"print(\"=== 一条消息的丢失窗口：三段链路逐项检查 ===\")\nprint()\nprint(\"链路: 生产者 -> broker(存储) -> 消费者 -> 业务库\")\nprint()\n\nCHECKS = [\n    (\"生产端\", \"acks\", \"acks=0\", \"「发送成功」不含任何持久化承诺\"),\n    (\"生产端\", \"攒批与退出\", \"未 flush() 就退出\", \"内存中攒批的消息随进程消失\"),\n    (\"生产端\", \"回调处理\", \"忽略 send() 的 Future\", \"失败被静默吞掉\"),\n…"}}]},{"id":"mw-ch07/02-duplicate-and-idempotence","file":"02-duplicate-and-idempotence.md","title":"二、重复消费的本质与业务幂等设计","kind":"timeline","secs":[{"h":"① 重复从哪里来：四个不变的来源","s":"1. 生产者重试：网络超时但 broker 已写入，客户端重试造成同一条消息落盘两次。","c":null},{"h":"② 幂等设计三件套：唯一键、去重表、状态机","s":"1. 数据库唯一索引（首选）：INSERT ... ON CONFLICT DO NOTHING / 唯一键冲突捕获。零额外依赖、天然并发安全、成本最低。","c":null},{"h":"③ 幂等落库的正确写法（代码级）","s":"以下是最常见的三种错误写法与对应正确写法（示例 x02、x08 会实测对比）：","c":null},{"h":"可运行代码：用唯一键把「去重」压进一个事务","s":"幂等消费最常见也最可靠的做法，是把「消息 id」变成数据库的唯一约束，让重复投递自己撞墙：","c":{"lang":"sql","code":"CREATE TABLE consumed_msg (\n  msg_id      VARCHAR(64) PRIMARY KEY,      -- 唯一键就是去重闸门\n  topic       VARCHAR(64) NOT NULL,\n  consumed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\n-- 业务写入与去重记录放在同一个事务里\nBEGIN;\nINSERT INTO consumed_msg (msg_id, topic) VALUES ('m-1001', 'order-created');\n…"}},{"h":"小结","s":"","c":null}]},{"id":"mw-ch07/03-ordering-guarantee","file":"03-ordering-guarantee.md","title":"三、顺序消息：边界、实现与代价","kind":"flow","secs":[{"h":"① 三种「顺序」必须先分清","s":"1. 分区内顺序：同一个 partition 内的消息按 offset 递增，这是 Kafka 的天然保证（只要不启用压缩分区的特殊语义）。","c":null},{"h":"② 顺序被打破的四个具体位置","s":"按发生频率排序：","c":{"lang":"java","code":"// 保序 + 可重试的最小生产者配置\nprops.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, true);          // 重试不再乱序\nprops.put(ProducerConfig.MAX_IN_FLIGHT_REQUESTS_PER_CONNECTION, 5); // 幂等下的上限，>5 会被拒\nprops.put(ProducerConfig.ACKS_CONFIG, \"all\");\nprops.put(ProducerConfig.RETRIES_CONFIG, Integer.MAX_VALUE);\n// 分区器必须稳定：不要用依赖随机数/时间戳的自定义分区器，\n// 也不要在运行期增加分区数——两者都会让同一个 key 换到别的分区\nproducer.send(new ProducerRecord<>(\"orders\", orderId, payload));    // key 决定分区"}},{"h":"③ 代价与替代方案","s":"若只需「同实体有序」，可把顺序粒度收到 key 级（多数场景已经足够）。","c":{"lang":"python","code":"class ReorderBuffer:\n    \"\"\"按版本号吸收乱序：只有前序到齐才放行，缺号就等\"\"\"\n\n    def __init__(self):\n        self.want = {}      # key -> 期望的下一个 seq\n        self.buf = {}       # key -> {seq: msg}\n\n    def push(self, key, seq, msg):\n        want = self.want.get(key, 1)\n…"}},{"h":"小结","s":"","c":null}]},{"id":"mw-ch07/04-transaction-retry-and-dlq","file":"04-transaction-retry-and-dlq.md","title":"四、事务、重试与死信：把手段组合成链路","kind":"timeline","secs":[{"h":"① 事务消息买到了什么、没买到什么","s":"事务消息在理论上的定位是「把两个副作用纳入同一个原子边界」。这个边界的大小直接决定了方案能力：","c":{"lang":"java","code":"// 事务生产者的骨架：关键在「位移提交与输出在同一个事务里」\nproducer.initTransactions();                    // transactional.id 必须唯一且稳定\ntry {\n    producer.beginTransaction();\n    producer.send(new ProducerRecord<>(\"out\", key, result));\n    consumer.commitSync();                      // 位移提交也进事务 -> 不再重复\n    producer.commitTransaction();\n} catch (ProducerFencedException e) {\n    producer.close();                           // 被新实例接管，旧实例必须退出\n…"}},{"h":"② 重试策略：可重试与不可重试要分开","s":"对不可重试异常重试 N 次只是浪费时间并把失败放大成风暴。","c":null},{"h":"③ 死信队列：隔离坏消息，而不是修好坏消息","s":"DLQ 的本质是故障隔离（fault isolation）与可用性优先的取舍：用「放弃单条消息的即时处理」换取「整条链路继续工作」。","c":null},{"h":"小结","s":"","c":null}]}],"exams":[{"kind":"choice","q":"acks=all 与 min.insync.replicas 的联合语义","stem":"下面关于 acks=all 的说法，哪一项正确？","opts":[{"k":"A","t":"acks=all 要求所有副本（含尚未同步的 follower）都写入成功才返回"},{"k":"B","t":"acks=all 的强度等于 min(ISR 实际大小, min.insync.replicas)；当 min.insy…"},{"k":"C","t":"acks=all 与 min.insync.replicas 无关，只要设了 all 就不会丢消息"},{"k":"D","t":"acks=all 只能用于单副本 topic，多副本时必须用 acks=1"}],"ans":"B","why":"acks=all 保证的是「当前 ISR 全体接受」，而 ISR 是会缩容的动态集合。要使它有意义，必须同时设置 min.insync.replicas >= 2，否则 ISR 缩到 1 个副本时仍接受写入，该副本一挂就丢。"},{"kind":"choice","q":"什么情况下生产者重试会导致分区内乱序","stem":"关于生产者重试导致的乱序，下列哪一项正确？","opts":[{"k":"A","t":"只要 retries>0 就一定乱序，与其它参数无关"},{"k":"B","t":"max.in.flight.requests.per.connection>1 且未开启幂等时，重试可能乱序；开启幂等后…"},{"k":"C","t":"乱序只发生在消费者端，与生产者重试无关"},{"k":"D","t":"开启幂等后必须把 in.flight 设为 1 才能保证有序"}],"ans":"B","why":"单分区在无故障时天然有序，但重试会让 broker 的接收顺序与发送顺序不一致。开启 enable.idempotence=true 后 broker 按序列号校验、缓存乱序消息并丢弃重复序列号，从而在允许 max.in.flight<=5 的同时保住分区内有序（示例 x05 实测）。"},{"kind":"fix_error","q":"修正消费者位移提交顺序","stem":"下面是消费者主循环，存在丢失消息的风险。请指出问题并给出正确写法。 java while (true) { ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(500)); consumer.commitSync(); // (A) for (ConsumerRecord<String, String>…","opts":[],"ans":"(A) 在 (B) 之前执行 -> 这是 at-most-once：处理失败时消息已被跳过，永久丢失。位移提交必须严格晚于处理成功。","why":"位移提交时机决定了交付语义：先提交后处理 = at-most-once（可能丢），先处理后提交 = at-least-once（可能重）。示例 x03 用崩溃点枚举量化了两种写法的窗口。"},{"kind":"choice","q":"幂等落库的正确写法","stem":"要在订单表上实现幂等落库（order_no 有唯一索引），下面哪种写法在并发重复投递下是正确的？","opts":[{"k":"A","t":"先 SELECT 判断 order_no 是否存在，不存在再 INSERT"},{"k":"B","t":"INSERT ... ON CONFLICT (order_no) DO NOTHING，把原子性下沉到存储引擎"},{"k":"C","t":"用 REPLACE INTO，冲突时直接覆盖"},{"k":"D","t":"在应用层加一把 synchronized 锁，然后普通 INSERT"}],"ans":"B","why":"「先查后写」在并发下必然存在双写窗口（示例 x02 实测 3 个并发请求全部写入）。REPLACE INTO 语义是删除 + 插入，会把未指定字段置为默认值并可能触发级联。仅「忽略异常」也不够——需要区分重复消息与真实业务冲突。"},{"kind":"output","q":"重试风暴的判据为什么不能用耗时","stem":"示例 x07 对比了三种重试策略的请求量。请说明： 1. 为什么「重试次数越多越可靠」是错误的？ 2. 该示例用什么作为量化判据？为什么不用耗时？","opts":[],"ans":"无退避策略的峰值请求量是基线的若干倍且逐轮翻倍；指数退避+抖动+上限把峰值压回常数倍，累计请求量显著下降。","why":"重试相当于提高到达率 λ：当 λ 逼近服务率 μ 时排队长度发散，形成重试风暴。必须配退避（含抖动）+ 次数上限 + 重试预算/熔断。判据用「请求计数」而非耗时，因为计数是确定性量（任何机器上一致），而耗时依赖机器负载，写进 expected_output 会导致复验失败。"},{"kind":"output","q":"设计有界阻塞队列（生产端背压的有界缓冲）","stem":"仅在平台作答（本题只保留元数据与链接，不含题面正文）。 关联点：消息中间件的生产端之所以需要背压，本质上是因为缓冲区有界——无界缓冲只能把压力转移到内存直至 OOM。请在平台完成实现，并思考：该队列的容量与 Kafka 生产端的 buffer.memory 在语义上是否等价？","opts":[],"ans":"见平台用例。","why":"背压（backpressure）是可靠性的前置条件：只有有界缓冲才能让「下游变慢」及时传导到上游，而不是被缓冲区吸收成内存增长。这与 Kafka 生产端 buffer.memory 打满后 send() 阻塞（或抛 TimeoutException）是同一机制。"},{"kind":"coding","q":"实现带退避的重试执行器（异常分类 + 幂等短路）","stem":"实现 retry(fn, , max_attempts, base, is_retryable, is_done)： - is_done() 为 True 时直接返回 ('absorbed', waited)，表示该操作已被幂等吸收，不再执行； - is_retryable(exc) 为 False 时立即抛出，不重试； - 否则按指数退避重试，累计退避量记入 waited，超过 max_atte…","opts":[],"ans":"不可重试异常: 立即抛出, waited = 0；可重试异常: waited = base(2^n - 1)；is_done() 为真时直接返回 absorbed, waited 不再增长。","why":"三个要点：① 异常必须分类，不可重试的立即失败（否则制造重试风暴）；② 退避要指数增长并有上限；③ 幂等短路要放在重试之前，避免对已处理的操作重复施加副作用。生产环境还需在退避量上加抖动，并交给调度器而不是 sleep 阻塞线程。"},{"kind":"coding","q":"模拟消费循环：位移提交 + 重试上限 + 死信隔离","stem":"实现 consume(msgs, , max_retry, fail_kinds)：顺序消费消息，遇到 fail_kinds 中的消息时累计重试次数，超过 max_retry 则移入死信队列并继续前进。 返回 (processed, dlq, blocked_normal)，其中 blocked_normal 表示「若不允许跳过（坏消息原地重试）会被阻塞的正常消息条数」。","opts":[],"ans":"processed 为正常消息序列；dlq 为超限消息；blocked 为「不允许跳过时被阻塞的正常消息条数」。","why":"核心是必须能跳过：位移不能停在坏消息上，否则整条链路被一条脏数据拖死。代价是同 key 的因果顺序可能被打破（示例 x08 量化：死信隔离下未处理消息数 0，但同 key 顺序倒置 = 1；原地重试则倒置 0 却让整分区停摆），因此强顺序业务要谨慎使用死信队列，并配合告警 + 重放工具形成闭环。"}],"works":[{"h":"把 acks=all 当成「绝对不丢」","d":"它只保证「当前 ISR 全体接受」。若 min.insync.replicas=1，ISR 缩到 1 个副本时 acks=all 等价于 acks=1。必须成对设置 acks=all + min.insync.replicas>=2。"},{"h":"开着 unclean.leader.election.enable=true 却要求消息不丢","d":"该开关允许落后副本当 leader，会把已确认的消息回滚。多数业务应保持 false；只有在「可用性 >> 一致性」的场景才打开，且要明确接受回滚。"},{"h":"用 send() 的无回调重载然后忽略返回值","d":"异常被静默吞掉，消息在攒批阶段就可能因超时/过大而失败，而业务毫无感知。必须传回调并处理异常，或至少记录失败计数。"},{"h":"进程退出前不 flush()","d":"攒批中的消息随进程一起消失。优雅退出流程里必须包含 producer.flush() 并等待回调。"},{"h":"enable.auto.commit=true 却要求不丢","d":"自动提交发生在 poll() 内部，提交的是上一批位移，与业务处理成功与否完全解耦；处理中崩溃会永久丢失未处理消息。"},{"h":"先 commitSync() 再处理消息","d":"这是 at-most-once：处理失败时消息已被跳过。位移提交必须严格晚于处理成功。"},{"h":"用 commitAsync() 却不处理失败","d":"异步提交失败会被静默丢弃（它没有重试机制），导致下次重放更早的位移。若要异步，需在回调中判断是否可重试或择机 commitSync() 兜底。"},{"h":"处理耗时超过 max.poll.interval.ms 却不调整","d":"消费者被踢出组 → 分区重分配 → 重复消费甚至长时间停摆。要么调大该参数，要么削减单批处理量，或把处理异步化并缩短 poll 间隔。"}],"asks":[{"q":"Kafka 怎么保证消息不丢？","a":"必须分三段回答，缺一段都不完整。 ① 生产端：acks=all + 处理 send() 回调异常 + 进程退出前 flush()。注意 acks=all 的强度等于 min(ISR 实际大小, min.insync.replicas)。 ② 存储端：min.insync.replicas >= 2 且 unclean.leader.election.enable=false。前者防止 acks=a…","fu":["acks=all 什么情况下仍会丢？","unclean.leader.election.enable=true 的取舍是什么？"],"tag":"字节跳动/美团"},{"q":"重复消费能根治吗？你们怎么处理？","a":"不能根治，因为重复是 at-least-once 语义的必然产物——「不丢」是靠「宁可重放也不跳过」换来的。 工程正确姿势是让重复无害： 1. 首选数据库唯一索引：INSERT ... ON CONFLICT DO NOTHING / 捕获唯一键冲突。原子性由存储引擎保证，零额外依赖。 2. 其次状态机 CAS：UPDATE ... WHERE status='CREATED'，靠行锁 + 前置条…","fu":["幂等键为什么不能用消息 ID？","「先查后写」为什么在并发下不安全？"],"tag":"美团/阿里"},{"q":"Kafka 怎么保证消息顺序？","a":"先纠正问题本身：Kafka 只保证分区内有序，不保证全局有序。 三种顺序的边界： - 分区内有序：offset 递增，天然保证。 - 同 key 有序：靠分区器把同 key 路由到同一分区，依赖分区数不变且分区函数稳定。 - 全局有序：等价于单分区，并行度锁死为 1。 顺序被打破的四个位置： 1. 生产端 max.in.flight.requests.per.connection > 1 且未开幂…","fu":["全局有序的代价是什么？","增加分区为什么会破坏顺序？"],"tag":"字节跳动/腾讯"},{"q":"exactly-once 是怎么实现的？它真的端到端吗？","a":"先给结论：Kafka 的事务消息只能保证 Kafka 内部（消费位移 + 生产输出）的恰好一次；跨系统时不成立，工程上退化为「at-least-once + 幂等」。 实现机制：事务建立在幂等生产者之上——transactional.id 绑定 PID，把「位移提交」与「输出写入」放进同一事务，配合消费者 isolation.level=read_committed 才能看不到未提交消息（否则仍读…","fu":["read_committed 与 read_uncommitted 的区别？","事务消息的性能代价是什么？"],"tag":"蚂蚁/字节跳动"}]},{"id":"mw-ch08","subj":"middleware","title":"消息队列选型与工程实践","summary":"削峰填谷、系统解耦、异步化的收益与代价；Kafka / RabbitMQ / RocketMQ / Pulsar 的多维对比（吞吐、延迟、顺序、事务、运维成本）；消息积压的排查与扩容手段；死信与补偿链路；与 Redis Stream、数据库…","concepts":[{"id":"mw-ch08/01-mq-value-and-boundary","file":"01-mq-value-and-boundary.md","title":"MQ 的价值与边界：该不该上消息队列（mw-ch08）","kind":"timeline","secs":[{"h":"§1 三大价值：削峰填谷、系统解耦、异步化","s":"上游流量是脉冲式的（大促、定时任务、批量导入），下游处理能力是相对恒定的（数据库写入、第三方接口限流）。中间放一个能缓冲的队列，就让「峰值」被摊平成一个更长的、更低的水位。","c":null},{"h":"§2 引入 MQ 的代价：四类新增复杂度","s":"从「一个事务提交」变成「两阶段最终一致」：本地事务 + 消息投递。典型难题是本地事务与消息发送的原子性（先落库后发消息可能丢，先发后落库可能多），解法是本地消息表 / 事务消息 / 最大努力通知。","c":null},{"h":"§3 边界：什么时候用 Redis Stream / DB 轮询 / 同步 RPC 反而更合…","s":"轻量：不引入独立集群，复用已有 Redis。有消费者组、有待确认消息（PEL）。适合中小规模、允许丢失少量消息、且不想运维 Kafka 的场景。局限：受 Redis 内存限制，长期堆积成本高；持久化依赖 RDB/AOF，不如 Kafka…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"# 削峰填谷：脉冲流量 + 恒定消费，需要多大缓冲？\ndef simulate(peak_rate, peak_dur, steady_rate, buf_cap, total_sec=30):\n    \"\"\"prod[i] 为第 i 秒到达量；消费恒定为 steady_rate（受缓冲区非空约束）。\"\"\"\n    buf = 0          # 当前积压\n    peak_buf = 0\n    rejected = 0     # 因缓冲满被拒（反压）的量\n    for i in range(total_sec):\n        arrived = peak_rate if i < peak_dur else 1\n        # 先消费（缓冲区已有数据）\n…"}}]},{"id":"mw-ch08/02-selection-matrix","file":"02-selection-matrix.md","title":"选型对比矩阵：Kafka / RabbitMQ / RocketMQ / Pulsar（mw-ch08）","kind":"compare","secs":[{"h":"§1 五个维度的对比框架","s":"四个系统可沿「存储模型」轴区分：Kafka/RocketMQ 是日志式追加写（append-only log，读靠 offset），天然支持重放与顺序；RabbitMQ 是队列式消费即删（消费确认后移除），语义更接近传统 MQ；Puls…","c":null},{"h":"§2 消息模型与路由能力","s":"发布到 topic，按 key 哈希落到 partition。没有 exchange/binding 概念，路由能力弱但简单。多订阅者靠不同消费者组各自维护 offset。","c":null},{"h":"可运行代码：先过硬约束，再加权打分","s":"「先约束过滤、再加权评分」这个流程写成代码只有十几行，但顺序反了就会选出错的方案：","c":{"lang":"python","code":"CANDIDATES = {\n    \"kafka\":    {\"吞吐\": 10, \"延迟\": 6, \"运维\": 5, \"事务消息\": True},\n    \"rabbitmq\": {\"吞吐\": 4,  \"延迟\": 9, \"运维\": 7, \"事务消息\": False},\n    \"rocketmq\": {\"吞吐\": 9,  \"延迟\": 7, \"运维\": 6, \"事务消息\": True},\n    \"pulsar\":   {\"吞吐\": 9,  \"延迟\": 7, \"运维\": 3, \"事务消息\": True},\n}\nWEIGHTS  = {\"吞吐\": 0.4, \"延迟\": 0.3, \"运维\": 0.3}\nMUST_HAVE = {\"事务消息\": True}          # 硬约束：不满足直接淘汰，不参与打分\n\n…"}},{"h":"§3 选型的工程判据","s":"把需求写成五个问题：日峰值消息量？可接受的端到端延迟？是否要求顺序？是否需要事务消息？团队有没有对应运维经验？ 五个答案基本能唯一确定选型。","c":null}]},{"id":"mw-ch08/03-backlog-diagnosis-and-scaling","file":"03-backlog-diagnosis-and-scaling.md","title":"消费积压：诊断与扩容（mw-ch08）","kind":"flow","secs":[{"h":"§1 积压的数学：四个变量","s":"设某 topic 有 $n$ 个分区，每个分区有 $c_i$ 个消费者（Kafka 下一个分区同时只能被同组内一个消费者消费，故有效并行度是 $\\min(\\text{分区数}, \\text{消费者数})$）。","c":null},{"h":"§2 分区数上限与突破路径","s":"Kafka 语义：同一消费者组内，一个分区只能分配给一个消费者。因此组内有效并行度 $= \\min(n, C)$。当 $C > n$，多出的消费者处于 idle 状态，只在 rebalance 后顶替故障者。","c":null},{"h":"§3 压测与容量规划","s":"先测单分区单消费者的处理速率 $\\rho$，这是所有估算的地基。它受下游 IO 主导，与 Kafka 本身关系不大（消费慢十有八九是业务逻辑慢）。","c":null}]},{"id":"mw-ch08/04-dlq-compensation-and-ops","file":"04-dlq-compensation-and-ops.md","title":"死信、补偿与运维实践（mw-ch08）","kind":"timeline","secs":[{"h":"§1 重试策略：可重试与不可重试","s":"分类是重试设计的第一性前提。不做分类就无脑重试，是「重试风暴」的根源。","c":null},{"h":"§2 一致性补偿：对账是最后一道防线","s":"当「本地事务成功但消息发送失败」或「消息消费成功但业务回滚」发生时，靠定时对账修复：定期比对「应有状态」与「实际状态」，把差异补上。对账是最终一致性的兜底，比任何重试都可靠，因为它不依赖失败那一刻的信息。","c":null},{"h":"§3 可观测性与运维","s":"不要用绝对阈值（「Lag > 10000 告警」）——不同 topic 量级差几个数量级。用趋势与相对值：Lag 增长率持续为正超过 N 分钟、清空时间估算超过 SLA、死信数环比突增。","c":null},{"h":"§4 工程实践清单（可上生产）","s":"1. 选型：需求五问 -> 决策表 -> 团队能力复核。","c":null}]},{"id":"mw-ch08/05-mq-selection-playbook","file":"05-mq-selection-playbook.md","title":"选型与运维实战：把 MQ 选型落成可执行的清单","kind":"flow","secs":[{"h":"一、先看决策维度，再看产品","s":"","c":{"lang":"text","code":"┌──────────────┬────────────────────────┬────────────────────────┐\n│ 维度          │ RabbitMQ               │ Kafka                  │\n├──────────────┼────────────────────────┼────────────────────────┤\n│ 投递语义      │ 逐条 ack/nack，可重投    │ 按 offset 提交，批量确认 │\n│ 路由能力      │ 交换机/队列/主题灵活      │ 只能按分区消费，路由弱   │\n│ 单条延迟      │ 毫秒级（低吞吐时更优）    │ 毫秒~十毫秒（批量更大） │\n│ 峰值吞吐      │ 万级/秒（多实例可堆）     │ 百万级/秒              │\n│ 顺序保证      │ 队列内 FIFO            │ 分区内有序（全局无序）   │\n│ 回放/重\n…"}},{"h":"二、逐条 ack 的语义（RabbitMQ 风格）","s":"注意最后那句 basic_ack：进了死信也要 ack，否则原队列的消息会一直重投，形成毒丸（poison pill）。","c":{"lang":"python","code":"# 逐条确认：处理成功才 ack；失败 nack(requeue=True) 回到队列，失败次数超限进死信\nimport json, time\nfrom collections import defaultdict\n\nMAX_RETRY = 3\nattempts = defaultdict(int)\n\ndef handle(channel, delivery):\n    body = json.loads(delivery.body)\n…"}},{"h":"三、按 offset 消费的语义（Kafka 风格）","s":"若要\"恰好一次\"，改用 Kafka 事务（transactional.id + send_offsets_to_transaction），","c":{"lang":"python","code":"# 手动提交位移：处理完这一批再提交 offset，保证\"至少一次\"\nimport json, time\n\ndef poll_loop(consumer, batch_size=500, poll_timeout_ms=1000):\n    while True:\n        records = consumer.poll(timeout_ms=poll_timeout_ms, max_records=batch_size)\n        if not records:\n            continue\n        processed = []\n…"}},{"h":"四、容量与降级清单（按顺序过）","s":"","c":{"lang":"yaml","code":"# 1) 容量：按峰值算，并留故障余量\ncapacity:\n  peak_msgs_per_sec: 20000\n  target_utilization: 0.65          # 稳态利用率不超过 0.65\n  n_minus_1_capacity_check: true    # 挂掉一个分区/节点后仍能扛住峰值\n  avg_msg_bytes: 1024\n  retention: 7d\n\n# 2) 降级顺序（先牺牲什么）\n…"}},{"h":"🧑‍💻 程序员视角","s":"选型先看「语义需求」再看产品：需要「逐条 ack + 复杂路由」选 RabbitMQ，需要「高吞吐 + 按 offset 回溯」选 Kafka，需要「事务消息 + 顺序」选 RocketMQ。容量评估按「峰值 TPS × 消息大小 ×…","c":null},{"h":"🎓 博士生视角","s":"MQ 的选型维度可归纳为「语义（ack/顺序/事务）× 吞吐 × 运维成本 × 生态」。RabbitMQ 的 AMQP 模型提供灵活路由但吞吐受限于单队列；Kafka 的分区日志模型吞吐高但路由能力弱；RocketMQ 在两者之间，额外…","c":null},{"h":"📚 考研者视角","s":"后端面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"削峰填谷能解决什么、不能解决什么","stem":"关于消息队列的「削峰填谷」，下列哪一项说法错误？","opts":[{"k":"A","t":"削峰填谷平滑的是到达时间分布，并不减少总工作量"},{"k":"B","t":"当生产速率长期大于消费速率时，积压会单调增长、永不清空"},{"k":"C","t":"队列把「瞬时高并发」转成「平稳低并发」交给消费端处理"},{"k":"D","t":"只要加了消息队列，消费端就永远不会被压垮"}],"ans":"D","why":"削峰填谷解决的是时间维度的错配：把尖峰摊到谷时。它不解决产能不足——那是空间/资源维度的问题。判断标准是净增速 r_p - r_c：为正则积压线性增长且永不清空，加多少缓冲也只是把崩溃时刻推迟。示例 x05 用四条用例把三态（增长 / 持平 / 清空）分开展示。"},{"kind":"choice","q":"原生事务消息的归属","stem":"在 Kafka / RabbitMQ / RocketMQ / ActiveMQ 中，原生支持事务消息（半消息 + 事务回查）的是哪一个？","opts":[{"k":"A","t":"Kafka"},{"k":"B","t":"RabbitMQ"},{"k":"C","t":"RocketMQ"},{"k":"D","t":"ActiveMQ"}],"ans":"C","why":"四点务必区分清楚：① Kafka 有事务，但只覆盖「分区写入 + 位移提交」的原子性，不覆盖外部数据库，因此跨系统一致性仍需业务兜底（示例 x12 对比了状态机）；② RabbitMQ 只有 channel 级 tx 与 publisher confirm，没有半消息概念；③ RocketMQ 原生事务消息，是「本地事务与消息发送原子性」的现成解法；④ ActiveMQ 走 X…"},{"kind":"fix_error","q":"修正积压告警的判据","stem":"下面是一段积压告警逻辑，它在「临界」状态下会永远不告警（积压持平、永不自愈），请指出问题并修正。\\n\\npython\\ndef should_alert(backlog_now, backlog_1min_ago):\\n return backlog_now > 100000 # 只看绝对水位\\n","opts":[],"ans":"只看绝对水位会漏掉两类最危险的情况：(a) 斜率恒为正但水位尚低（迟早爆）；(b) 斜率恒为零且存量很大（永远不恢复）。判据必须同时看水位与斜率。","why":"积压由四个变量决定：生产速率 r_p、消费速率 r_c、分区数 P、单条处理耗时。只监控水位等于只看积分量而不看导数：r_p == r_c 时水位恒定、看板一片绿，但任何一次尖峰都会把水位永久抬高一级（示例 x05 第二行专门演示了这一态）。正确做法是水位 + 斜率双判据，并额外监控「按当前斜率预计的清空时间」。"},{"kind":"output","q":"给定速率算清空时间与所需缓冲","stem":"某 topic 大促期间：生产 1500 条/s、消费 1000 条/s，峰值持续 120 秒后回落到生产 600 条/s、消费仍为 1000 条/s。\\n\\n请回答：\\n1. 峰值结束时积压多少条？\\n2. 之后需要多久清空？\\n3. 如果消费能力只能提到 900 条/s（峰值过后不变），能清空吗？","opts":[],"ans":"1) 峰值 120s 内净增 (1500-1000)120 = 60000 条；\\n2) 回落后清空时间 = 60000 / (1000-600) = 150 秒；\\n3) 不能——回落期生产 600 条/s 低于消费 900 条/s，仍可清空，但若生产未回落则永远清不掉。","why":"三个量由同一个模型给出：净增速 r_p - r_c 决定能否清空，清空时间 T = L0 / (r_c - r_p) 决定恢复时长，峰值缓冲 L0 = (r_p - r_c) × T_peak 决定磁盘与告警水位。注意这是确定性流体近似：真实系统在利用率接近 1 时排队延迟会急剧上升，实际清空时间会显著长于公式值。"},{"kind":"choice","q":"消费者数超过分区数之后","stem":"某 topic 有 6 个分区，消费者组已有 6 个消费者且分区均匀分配。此时再启动第 7 个消费者，会发生什么？","opts":[{"k":"A","t":"触发 rebalance，6 个分区被 7 个消费者均分，吞吐提升"},{"k":"B","t":"多出的消费者分不到分区、处于空闲，吞吐不再增长——分区数就是并行度上限"},{"k":"C","t":"直接报错，消费者组拒绝新成员加入"},{"k":"D","t":"集群自动扩容分区数，以匹配消费者数量"}],"ans":"B","why":"这是积压扩容最常见的一次无效操作。并行度 = min(消费者数, 分区数)，因此扩容前必须先看分区数——示例 x06 用 (分区数, 消费者数) 组合矩阵做了实证：达到分区数上限后继续加消费者，有效并行度与吞吐量都不再变化。若确需更高并行度，只能提前把分区数留足（Kafka 只能增不能减），或改用批量消费 / 提升单条处理并行度。"},{"kind":"coding","q":"实现积压画像函数","stem":"实现 backlog_profile(rate_produce, rate_consume, initial=0)，返回 (can_drain, drain_time)：\\n- rate_produce > rate_consume：积压单调增长，返回 (False, None)；\\n- 两者相等：积压持平、永不自愈；仅当 initial == 0 时返回 (True, None)，否则 (Fal…","opts":[],"ans":"全部断言通过","why":"三态判定是全部积压结论的基础：净增速为正是「恶化」，为零是「持平但永不自愈」（最容易被监控漏掉），为负才是「可恢复」。net == 0 与 initial == 0 的边界必须单独处理——初始为空且速率相等时系统本来就是健康的，写成 net >= 0 -> False 会造成误报。"},{"kind":"coding","q":"实现 MQ 选型打分器","stem":"实现 select(weights, require_tx=False, require_tenant=False)：\\n\\n1. 硬约束过滤：require_tx=True 时剔除 tx_msg 为 False 的候选；require_tenant=True 时剔除 multi_tenant 为 False 的候选。被剔除的返回为 [(名称, 原因), ...]，原因分别为 无事务消息 / 不支…","opts":[],"ans":"Kafka RocketMQ","why":"选型必须先硬约束、后打分：若把「无事务消息」当成一个可以扣分的维度，一个吞吐极高的候选仍可能靠总分取胜，从而在订单链路上出事。硬约束是资格线，权重是排序线，两者语义不同、不可混算。另外权重必须随场景重排（示例 x04 用三个场景演示：日志管道选 Kafka、订单状态机选 RocketMQ、延迟敏感通知选 RabbitMQ），同一套权重套所有场景本身就是选型失败的主因。"},{"kind":"coding","q":"最近请求次数（时间窗口到达率统计）","stem":"题目与输入输出格式见 LeetCode 原题（链接见下）。本题只保留元数据，题面不在此搬运。\\n\\n与本章的联系：诊断积压的第一步是测准生产速率 r_p，而 r_p 的定义就是「最近 T 时间窗内到达的消息数 / T」。滑动窗口计数是它的最小实现。","opts":[],"ans":"[1, 2, 3, 3]","why":"队列里只保留窗口内的时刻，每个元素进出各一次，因此均摊 O(1)、总体 O(n)。工程含义：用定长窗口而不是累计计数来估计速率，累计计数会把历史峰值永远带在身上，导致对当前状况判断失真——这与「积压告警只看绝对水位」是同一类错误（示例 x11 用清空时间的敏感性分析说明口径选择的影响）。"}],"works":[{"h":"把 MQ 当\"性能加速器\"","d":"MQ 不提升单条处理速度，只是流量整形与解耦。若下游本身吞吐不足，上了 MQ 只是把延迟变成积压。正确做法是先确认下游有水平扩展能力。"},{"h":"不做异常分类就重试","d":"参数错误、反序列化失败这类异常重试一万次也不会成功，只会拖垮队列。正确做法是区分可重试与不可重试，后者直接进死信。"},{"h":"加消费者突破不了分区数上限","d":"同组内一个分区只能给一个消费者，消费者数超过分区数后新增的只会空闲。此时应压单条耗时或加分区（有副作用）。"},{"h":"先加分区再想办法","d":"改分区数会打乱 key 哈希路由，同一实体的消息可能落到不同分区，顺序彻底失效，且不可回退。应先优化处理耗时。"},{"h":"只监控条数 Lag","d":"消息大小不均时条数 Lag 会严重误导（1000 条 1KB 与 10 条 1MB 天差地别）。应同时监控字节 Lag。"},{"h":"死信队列没有告警与处理入口","d":"死信等于黑洞，坏消息堆到磁盘满也没人知道。死信必须有告警 + 定期补偿重放流程。"},{"h":"依赖\"最终一致\"却不做对账","d":"重试和对账解决的是不同问题：重试处理瞬时失败，对账修复永久不一致。缺少对账，链路上任何一处静默失败都会变成长期数据错误。"},{"h":"追求端到端 exactly-once","d":"Kafka 事务只覆盖\"分区写入 + 位移提交\"的原子性，不覆盖外部系统。跨系统 exactly-once 成本极高，工程上应选 at-least-once + 幂等。"}],"asks":[{"q":"消息队列的三大用途是什么？各自的代价是什么？","a":"① 异步解耦：把调用方从「必须等被调方成功」里解放出来。代价是一致性从强变弱——同步 RPC 的失败是立刻可见的，异步事件的失败要等重试链路走完才知道（示例 x02 用「故障波及服务数」量化：同步链 7 个，异步 3 个，因为异步把故障限制在消费侧）。 ② 削峰填谷：把脉冲流量摊平。代价是引入积压，需要磁盘容量、积压告警与清空时间预估。注意它不解决长期产能不足——净增速为正时加多少缓冲都只是推迟崩…","fu":["什么时候不该用 MQ？（提示：需要强一致读、调用链极短、量小且稳定）","异步化之后，用户看到的「成功」是什么意思？"],"tag":"字节跳动/美团"},{"q":"让你选 MQ，你的决策顺序是什么？","a":"四步，顺序不能反： ① 定硬约束（资格线，不参与打分）：是否必须事务消息、是否要多租户、是否要跨地域复制、是否有严格顺序要求。这一步直接砍掉不合资格的候选——Kafka 与 RabbitMQ 没有原生事务消息，订单类场景直接出局。 ② 定业务权重（排序线）：把吞吐、延迟、顺序、事务、运维成本按本场景的相对重要度排序并赋权。日志管道吞吐为王，延迟敏感通知低延迟为王，权重必须按场景重排。 ③ 打分并核…","fu":["如果团队已经有一整套 RabbitMQ 运维体系，你会为吞吐选 Kafka 吗？","Pulsar 的存算分离带来什么好处与代价？"],"tag":"阿里/腾讯"},{"q":"线上消息积压了，你的排查顺序是什么？","a":"用四变量模型把问题拆开，逐个量测而不是猜： ① 测生产速率 r_p：按最近 T 窗口（而非累计）统计到达量，确认是流量真的涨了，还是发送端重试放大（重试风暴会让 r_p 虚高）。 ② 测消费速率 r_c 与单条处理耗时：如果 r_c 骤降，先看下游依赖（数据库慢查询、第三方 API 超时）——积压常常只是下游故障的表象。 ③ 算净增速与清空时间：r_p - r_c > 0 则积压只会更糟；用 T…","fu":["怎么区分「流量涨了」和「消费变慢了」？","为什么说「加消费者」是最容易无效的一次操作？"],"tag":"字节跳动/美团"},{"q":"Kafka / RabbitMQ / RocketMQ / Pulsar 的核心差异是什么？","a":"按数据模型分两组，比背参数有用得多： 日志型（Kafka、Pulsar）：消息是可重放的日志，消费位点属消费者而非 broker，因此天然支持多消费者组独立消费、按 offset 回放。代价是顺序只保证分区内，且延迟通常在毫秒级而非微秒级。Pulsar 额外做存算分离（broker 无状态 + BookKeeper 存储），扩缩容更灵活、支持多租户，但组件更多、运维更重。 队列型（RabbitMQ…","fu":["为什么 Kafka 的顺序只保证分区内？跨分区全局有序怎么实现？","Pulsar 的存算分离在什么场景下收益最大？"],"tag":"阿里/字节跳动"}]}];

export default CHAPTERS;
